-- KÖK&KOD demo verisi: yönetim panelini demo videosu için doldurur (7 Kas 2026).
-- Supabase SQL Editor'da BİR KEZ çalıştır. Geri almak için: demo_temizle.sql.
-- Eklenen her satır public.demo_kayitlari tablosuna yazılır; temizlik yalnız onları (ve onlardan doğan kayıtları) siler.
-- Hiçbir kayıt 'yayinda' girmez, canlı sitedeki eser metinleri değişmez.
-- Öneriler ilk Sistem yöneticisinin hesabına bağlanır (tablo kullanıcı kimliği istiyor); ekranda gönderen adı demo kişidir.

create table if not exists public.demo_kayitlari (
  tablo text not null,
  kayit text not null,
  primary key (tablo, kayit)
);
alter table public.demo_kayitlari enable row level security;

do $demo$
declare
  sid bigint;
  oid_ bigint;
  aid bigint;
  ben uuid;
  tid uuid;
begin
  if exists (select 1 from demo_kayitlari) then
    raise exception 'Demo verisi zaten yüklü. Yeniden yüklemek için önce demo_temizle.sql çalıştır.';
  end if;
  select kullanici into ben from kullanici_rolleri where rol = 'super_admin' order by tarih limit 1;
  if ben is null then raise exception 'Sistem yöneticisi bulunamadı.'; end if;

  -- Kaynak kütüphanesi
    values ('demo-tdv-hunat-hatun', 'Hunat Hatun Külliyesi (madde)', 'baglanti', 'ikincil', 'akademik', 'https://islamansiklopedisi.org.tr/hunat-hatun-kulliyesi', null, 'TDV İslâm Ansiklopedisi', null, 'dogrulandi', false, 'Selin Aydın', now() - interval '150 hours', 'Murat Kaplan', now() - interval '147 hours', 'Kayseri eserleri için ansiklopedi maddesi.');
