    values ('demo-saha-selcuk-hatun', 'Selçuk Hatun Camii kitâbe fotoğrafı (saha çalışması)', 'kayit', 'birincil', 'diger', null, 'Selin Aydın', null, 2026, 'dogrulanmamis', false, 'Selin Aydın', now() - interval '2 hours', null, null, 'Giriş kapısı üzerindeki kitâbenin fotoğrafı; okuma danışmana gönderilecek.');

