  -- Eser sürümleri
  -- furgan-dede-mescidi-konya (incelemede)
    values ('furgan-dede-mescidi-konya', 'konya', '{"id": "furgan-dede-mescidi-konya", "ad": {"tr": "Furgan Dede Mescidi", "en": "Furgan Dede Masjid"}, "tur": "mescit", "ilce": "Meram", "adres": {"tr": "Mescit, Meram, Akbaş Mahallesi, Kamani Mehmet Paşa Sokak, No. 9’da yer almaktadır.", "en": "The masjid is located in Meram District, Akbaş Neighborhood, Kamani Mehmet Paşa Street No: 9. The work was commissioned by Furgan Dede, whose grave is located in the western part of the narthex."}, "donem": {"yapim_yili": 1908, "kaynak_id": "vk-konya-envanter-c1", "sayfa": "83"}, "konum": {"enlem": 37.865747, "boylam": 32.492593, "dogrulandi": false, "yontem": "geocoding", "hassasiyet": "mahalle"}, "envanter": {"kaynak_id": "vk-konya-envanter-c1", "sayfa": "83"}, "olgular": [{"metin": {"tr": "Mescit, Meram, Akbaş Mahallesi, Kamani Mehmet Paşa Sokak, No. 9’da yer almaktadır.", "en": "The masjid is located in Meram District, Akbaş Neighborhood, Kamani Mehmet Paşa Street No: 9. The work was commissioned by Furgan Dede, whose grave is located in the western part of the narthex."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "83"}, {"metin": {"tr": "Eser, son cemaat yerinin batı bölümünde kabri bulunan Furgan Dede tarafından yaptırılmıştır. Mescide ismini de vermiş olan Furgan Dede’nin Horasan erenlerinden bir muhterem veyahut Mevlâna Celaleddin-i Rûmi’nin müritlerinden birisi olduğu düşünülmektedir.", "en": "It is thought that Furgan Dede, who gave his name to the mosque, was one of the Khorasan saints or one of the disciples of Mevlâna Celaleddin-i Rûmi."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "83"}, {"metin": {"tr": "Mescit 1908 senesinde inşa edilmiştir ve kuzey-güney yönünde uzanan dikdörtgen plana sahiptir. Mescit içten bağdadi bir kubbeyle, dıştan ise kırma çatıyla örtülmüştür.", "en": "The masjid was built in 1908 and has a rectangular plan extending in the north-south direction. The mosque is covered with a dome from the inside and a hipped roof from the outside. There are two windows with flat lintels on the east facade. There are two windows with wooden triangular pediments and flat lintels on the north facade. There is a door opening with a flat lintel in the middle of the facade. There are two windows with flat lintels on the south facade and another window on the mihrab axis."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "83"}, {"metin": {"tr": "Doğu cephesinde düz lentolu iki pencere görülmektedir. Kuzey cephede ahşap üçgen alınlıklı, düz lentolu iki adet pencere bulunmaktadır. Cephenin ortasında düz lentolu kapı açıklığı yer almaktadır. Güney cephede de düz lentolu iki pencere ve mihrap aksında bir pencere daha bulunmaktadır.", "en": "The interior has a rectangular plan extending in the north-south direction. A niche was opened in the eastern wall. There is a mihrab niche in the middle of the qibla wall."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "83"}, {"metin": {"tr": "İç mekân kuzey-güney yönünde uzanan dikdörtgen planlıdır. Doğu duvarında bir niş açılmıştır. Kıble duvarının ortasında da mihrap nişi yer almaktadır.", "en": "The interior is rectangular in plan, extending north to south. A niche is set in the east wall, and the mihrab niche stands in the middle of the qibla wall."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "83", "en_ceviri": "yz"}], "gorseller": [{"dosya": "/gorseller/konya/furgan-dede-mescidi-konya/01.webp", "alt": {"tr": "Furgan Dede Mescidi, fotoğraf 1", "en": "Furgan Dede Masjid, photo 1"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Konya Vakıf Eserleri Envanteri", "kaynak_id": "vk-konya-envanter-c1"}, {"dosya": "/gorseller/konya/furgan-dede-mescidi-konya/02.webp", "alt": {"tr": "Furgan Dede Mescidi, fotoğraf 2", "en": "Furgan Dede Masjid, photo 2"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Konya Vakıf Eserleri Envanteri", "kaynak_id": "vk-konya-envanter-c1"}], "banisi": "Furgan Dede"}'::jsonb, 'incelemede', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'furgan-dede-mescidi-konya' and durum = 'yayinda'), 'vk-konya-envanter-c1', '83', 'Bânî olgularda geçiyor ama künyede boştu; künyeye eklendi.', 'Selin Aydın', now() - interval '30 hours') returning id into sid;
    values ('kaynak', 'surum', sid, 'furgan-dede-mescidi-konya', 'demo', 'tamam', '{"sonuc": "destekliyor", "sayfa": 83, "pasaj": "Eser, son cemaat yerinin batı bölümünde kabri bulunan Furgan Dede tarafından yaptırılmıştır. Mescide ismini de vermiş olan Furgan Dede’nin Horasan erenlerinden bir muhterem veyahut Mevlâna Celaleddin-i Rûmi’nin müritlerinden birisi olduğu düşünülmektedir.", "kaynaktaki_deger": "Furgan Dede", "aciklama": "Kaynak, mescidin Furgan Dede tarafından yaptırıldığını açıkça yazıyor.", "guven": "yuksek", "metin": "tamam", "pasaj_dogrulandi": true, "bulunan_sayfa": 83, "sayfali": true, "kaynak_adresi": "https://www.vakifkatilim.com.tr/documents/KurumsalIletisim/yayinlarimiz/konya-envanteri-1_cilt-web.pdf", "incelenen_sayfalar": [82, 83, 84]}'::jsonb, 'gemini-flash-lite-latest', 'Sistem', now() - interval '29.5 hours', now() - interval '29.5 hours') returning id into aid;
  -- ayanbey-camii-konya (incelemede)
    values ('ayanbey-camii-konya', 'konya', '{"id": "ayanbey-camii-konya", "ad": {"tr": "Ayanbey Camii", "en": "Ayanbey Mosque"}, "tur": "cami", "ilce": "Meram", "adres": {"tr": "Cami, Meram, Ayanbey Sokak, No. 2’de yer almaktadır.", "en": "The Mosque is located Meram, Ayanbey Str."}, "donem": {"yaklasik": true, "metin": {"tr": "XIX. yüzyılın ortaları", "en": "Mid-19th century"}, "kaynak_id": "vk-konya-envanter-c1", "sayfa": "89"}, "konum": {"enlem": 37.865, "boylam": 32.48, "dogrulandi": false, "yontem": "geocoding", "hassasiyet": "ilce"}, "envanter": {"kaynak_id": "vk-konya-envanter-c1", "sayfa": "89"}, "olgular": [{"metin": {"tr": "Cami, Meram, Ayanbey Sokak, No. 2’de yer almaktadır.", "en": "The Mosque is located Meram, Ayanbey Str."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "89"}, {"metin": {"tr": "Ayan üyesi Memiş Paşa’nın oğlu Süleyman Bey tarafından XIX. yüzyılın ortalarında yaptırılmıştır.", "en": "No: 2."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "89"}, {"metin": {"tr": "Cami, kuzey-güney yönünde dikdörtgen planlıdır. İçten düz dam, dıştan kırma çatılıdır.", "en": "It was built by Süleyman Bey, the son of Memiş Paşa, a member of the Ayan, in the middle of the 19th century. The mosque has a rectangular plan in the north-south direction. It has a flat roof on the inside and a hipped roof on the outside."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "89"}, {"metin": {"tr": "Harim mihraba dikey üç sahından oluşmaktadır.", "en": "The harim consists of three aisles perpendicular to the mihrab."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "89"}, {"metin": {"tr": "Cephe görünümleri oldukça sadedir.", "en": "The facade views are quite plain."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "89"}, {"metin": {"tr": "Kuzey ve güney cephelerde iki, doğu cephede üç, batı cephede de dört pencere ile aydınlatılmaktadır.", "en": "It is illuminated by two windows on the north and south facades, three on the east facade and four windows on the west facade."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "89"}, {"metin": {"tr": "Kuzey cephenin ortasında giriş kapısı vardır.", "en": "There is an entrance door in the middle of the north facade."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "89"}, {"metin": {"tr": "Harime kuzey cephedeki düz lentolu çift kanatlı demir kapı ile girilmektedir. Girişin batı cephesinde, içeri çekilmiş bir minare yer almaktadır. Harim, kuzey-güney yönünde uzanan iki sıra hâlindeki ikişer ahşap destekle mihraba dik vaziyette üç sahına ayrılmıştır. İç mekânın kuzeyindeki mahfil batıdaki sahına doğru uzatılarak “L” şeklini almıştır. Kıble duvarının ortasında bulunan mihrap yarım daire kesitlidir ve ahşap malzemeden ajur tekniğiyle yapılmış, bitkisel motiflerle bezenmiştir. Tavanda yine ahşap malzemeden oyma tekniğiyle yapılmış bitkisel motiflerle süslü oval ve madalyon göbekler vardır.", "en": "Harim is entered through a double-winged iron door with a flat lintel on the north facade. There is a retracted minaret on the west side of the entrance. The harim is divided into three naves perpendicular to the mihrab, with two wooden supports in two rows extending in the north-south direction. The mahfil in the north of the interior space extends towards the nave in the west and took the shape of an “L”."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "89"}], "gorseller": [{"dosya": "/gorseller/konya/ayanbey-camii-konya/02.webp", "alt": {"tr": "Ayanbey Camii, fotoğraf 2", "en": "Ayanbey Mosque, photo 2"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Konya Vakıf Eserleri Envanteri", "kaynak_id": "vk-konya-envanter-c1", "odak": "50% 75%"}, {"dosya": "/gorseller/konya/ayanbey-camii-konya/01.webp", "alt": {"tr": "Ayanbey Camii, fotoğraf 1", "en": "Ayanbey Mosque, photo 1"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Konya Vakıf Eserleri Envanteri", "kaynak_id": "vk-konya-envanter-c1"}], "banisi": "Memiş Paşa oğlu Süleyman Bey"}'::jsonb, 'incelemede', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'ayanbey-camii-konya' and durum = 'yayinda'), 'vk-konya-envanter-c1', '89', 'Bânî ve yapım dönemi künyeye işlendi.', 'Selin Aydın', now() - interval '27 hours') returning id into sid;
    values ('kaynak', 'surum', sid, 'ayanbey-camii-konya', 'demo', 'tamam', '{"sonuc": "destekliyor", "sayfa": 89, "pasaj": "Ayan üyesi Memiş Paşa’nın oğlu Süleyman Bey tarafından XIX. yüzyılın ortalarında yaptırılmıştır.", "kaynaktaki_deger": "Ayan üyesi Memiş Paşa’nın oğlu Süleyman Bey; XIX. yüzyılın ortaları", "aciklama": "Bânî ve dönem kaynaktaki cümleyle aynı. Kesin yıl kaynakta yok, ''yaklaşık'' işareti doğru.", "guven": "yuksek", "metin": "tamam", "pasaj_dogrulandi": true, "bulunan_sayfa": 89, "sayfali": true, "kaynak_adresi": "https://www.vakifkatilim.com.tr/documents/KurumsalIletisim/yayinlarimiz/konya-envanteri-1_cilt-web.pdf", "incelenen_sayfalar": [88, 89, 90]}'::jsonb, 'gemini-flash-lite-latest', 'Sistem', now() - interval '26.5 hours', now() - interval '26.5 hours') returning id into aid;
