    values ('gazezler-camii-konya', 'konya', '{"id": "gazezler-camii-konya", "ad": {"tr": "Gazezler Camii", "en": "Gazezler Mosque"}, "tur": "cami", "ilce": "Meram", "adres": {"tr": "Cami Meram, Sahibiata Mahallesi, Furgan Dede Caddesi, No. 47’de yer almaktadır.", "en": "The mosque is located at Furgan Dede Str No: 47, Meram District, Sahibiata Neighborhood."}, "donem": {"yaklasik": true, "metin": {"tr": "XIX. yüzyıl başları", "en": "Early 19th century"}}, "konum": {"enlem": 37.866066, "boylam": 32.495941, "dogrulandi": false, "yontem": "geocoding", "hassasiyet": "adres"}, "envanter": {"kaynak_id": "vk-konya-envanter-c1", "sayfa": "80"}, "olgular": [{"metin": {"tr": "Cami Meram, Sahibiata Mahallesi, Furgan Dede Caddesi, No. 47’de yer almaktadır.", "en": "The mosque is located at Furgan Dede Str No: 47, Meram District, Sahibiata Neighborhood."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "80"}, {"metin": {"tr": "Adını Gazezler (İpekçiler) Mescidi’nden almaktadır.", "en": "It takes its name from the Gazezler (Ipekciler) Mosque."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "80"}, {"metin": {"tr": "Bu bölge Selçuklulardan bu yana Konya ipekçilerinin bulunduğu yerdir.", "en": "This region is where Konya silk merchants have been since the Seljuks."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "80"}, {"metin": {"tr": "Cami Ahmet Necip Efendi tarafından XIX. yüzyıl başlarında yaptırılmış olmalıdır.", "en": "Ahmet Necip Efendi must have had the mosque built in the early 19th century."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "80"}, {"metin": {"tr": "Cami kuzey-güney yönünde uzanan dikdörtgen planlıdır ve mihraba dikey uzanan üç sahından oluşmaktadır.", "en": "The mosque has a rectangular plan extending in the north-south direction and consists of three aisles extending perpendicular to the mihrab."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "80"}, {"metin": {"tr": "İçten düz dam, dıştan ise kırma çatıyla örtülüdür.", "en": "It is covered with a flat roof on the inside and a hipped roof on the outside."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "80"}, {"metin": {"tr": "Güney ve doğu cephelerde iki, batı cephede ise bir adet düz lentolu pencere yer almaktadır.", "en": "There are two windows with flat lintels on the south and east facades and one on the west facade."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "80"}, {"metin": {"tr": "Camiye girişi sağlayan iki giriş kapısından birisi kuzeydoğu cephede diğeri ise kuzeybatı cephede yer almaktadır.", "en": "One of the two entrance doors that provide access to the mosque is located on the north-east facade and the other is on the north-west facade."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "80"}, {"metin": {"tr": "Günümüzde kuzeydoğu cephede bulunan kapı kullanılmaktadır.", "en": "Today, the door on the northeast facade is used."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "80"}, {"metin": {"tr": "Harim mekânı kuzey-güney yönünde uzanan dikdörtgen bir plana sahiptir. İç mekân, iki sıra hâlinde üçer ahşap destekle mihrap duvarına dik gelecek şekilde üç sahına ayrılmıştır. Destekler birbirine ve beden duvarlarına Bursa kemeri ile bağlanmıştır.", "en": "The harim space has a rectangular plan extending in the north-south direction. The interior space is divided into three naves, perpendicular to the mihrab wall, with three wooden supports in two rows. The supports are connected to each other and to the body walls with a bursa belt. The mahfil in the north of the harim is placed in a “U” shape and is supported by wooden supports from below. The niche of the wooden mihrab in the middle of the qibla wall has a semicircular plan and was added to the building later. There is one niche on the east and west walls of the harim and two niches on the north wall."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "80"}, {"metin": {"tr": "Harimin kuzeyindeki mahfil “U” şeklinde yerleştirilmiştir ve alttan ahşap desteklerle taşınmaktadır. Kıble duvarının ortasındaki ahşap mihrabın nişi yarım daire planlıdır ve yapıya sonradan eklenmiştir. Harimin doğu ve batı duvarlarında bir, kuzey duvarında ise iki tane niş vardır.", "en": "The gallery on the north side of the prayer hall is U-shaped and carried on wooden supports. The niche of the wooden mihrab in the middle of the qibla wall is semicircular in plan and was added to the building later. The east and west walls of the prayer hall each have one niche, and the north wall has two."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "80", "en_ceviri": "yz"}], "gorseller": [{"dosya": "/gorseller/konya/gazezler-camii-konya/01.webp", "alt": {"tr": "Gazezler Camii, fotoğraf 1", "en": "Gazezler Mosque, photo 1"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Konya Vakıf Eserleri Envanteri", "kaynak_id": "vk-konya-envanter-c1"}, {"dosya": "/gorseller/konya/gazezler-camii-konya/02.webp", "alt": {"tr": "Gazezler Camii, fotoğraf 2", "en": "Gazezler Mosque, photo 2"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Konya Vakıf Eserleri Envanteri", "kaynak_id": "vk-konya-envanter-c1"}], "banisi": "Ahmet Necip Efendi"}'::jsonb, 'incelemede', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'gazezler-camii-konya' and durum = 'yayinda'), 'vk-konya-envanter-c1', '80', 'Bânî eklendi, dönem ''XIX. yüzyıl başları'' olarak yazıldı.', 'Burak Öztürk', now() - interval '52 hours', 'Doç. Dr. Zeynep Arslan', now() - interval '40 hours', null, 'Kaynak ''yaptırılmış olmalıdır'' diyor, yani kesin değil. Künyede bânînin yanına ''muhtemelen'' notu düşülsün ya da kitâbe kaydı eklensin.') returning id into sid;
    values ('kaynak', 'surum', sid, 'gazezler-camii-konya', 'demo', 'tamam', '{"sonuc": "destekliyor", "sayfa": 80, "pasaj": "Cami Ahmet Necip Efendi tarafından XIX. yüzyıl başlarında yaptırılmış olmalıdır.", "kaynaktaki_deger": "Ahmet Necip Efendi tarafından XIX. yüzyıl başlarında yaptırılmış olmalıdır", "aciklama": "Kaynak bilgiyi destekliyor ama ihtimal diliyle (''olmalıdır'') veriyor; kesin bilgi gibi yazılmamalı.", "guven": "orta", "metin": "tamam", "pasaj_dogrulandi": true, "bulunan_sayfa": 80, "sayfali": true, "kaynak_adresi": "https://www.vakifkatilim.com.tr/documents/KurumsalIletisim/yayinlarimiz/konya-envanteri-1_cilt-web.pdf", "incelenen_sayfalar": [79, 80, 81]}'::jsonb, 'gemini-flash-lite-latest', 'Sistem', now() - interval '51.5 hours', now() - interval '51.5 hours') returning id into aid;
  -- ahmediye-camii-hatay (incelemede)
    values ('ahmediye-camii-hatay', 'hatay', '{"id": "ahmediye-camii-hatay", "ad": {"tr": "Ahmediye Camii", "en": "Ahmediye Mosque"}, "tur": "cami", "ilce": "Antakya", "donem": {"yapim_yili": 1842, "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, "konum": {"enlem": 36.203431, "boylam": 36.163491, "dogrulandi": false, "yontem": "geocoding", "hassasiyet": "eser"}, "envanter": {"kaynak_id": "vk-hatay-envanter", "sayfa": "212"}, "olgular": [{"metin": {"tr": "Antakya’nın en merkezi ve kalabalık yerinde bir zamanlar medresesi de olan 1842 tarihli Ahmediye Camii, varlığını sürdürmeye devam ediyor.", "en": "The Ahmediye Mosque, built in 1842, which was once a madrasa in the most central and crowded place of Antakya, currently continues to exist with its mosque and shadirvan."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "Eserin banisi Ahmed Bey hakkında ise herhangi bir bilgi bulunmamaktadır.", "en": "There is no information about the builder of the work, Ahmed Bey."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "1941 yılında, Hatay’ın ana vatana kavuşmasından hemen sonra âdeta zafer nişanesi olarak yapıya eklenen yuvarlak gövdeli narin minare, harimin güney batısında bulunur.", "en": "The round-bodied delicate minaret, which was added to the building as a sign of victory in 1941, right after Hatay’s return to its homeland, is located in the south-west of the sanctuary."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "Minare yapıya oldukça zenginlik kazandırmıştır.", "en": "The minaret has added a lot of richness to the structure."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "Camii kapısı üstüne “Allah’ın mescitlerini ancak Allah’a ve ahiret gününe iman edenler imar eder.”", "en": "It is very meaningful that the verse “ Only those who believe in Allah and the Last Day will build the mosques of Allah.”"}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "(Tevbe, 18) ayetinin nakşedilmiş olması ise oldukça anlamlıdır.", "en": "(Tawba, 18) was engraved on the mosque door."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "Camii dikdörtgen plan üzerine taş malzemeyle yapılmıştır ve oldukça mütevazı bir görünüme sahiptir.", "en": "The mosque was built with stone material on a rectangular plan and has a very modest appearance."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "Tek ayak üzerine oturtulmuş, iki kemer gözünün oluşturduğu kıble duvarına paralel şekilde konumlanmış iki sahından meydana gelmektedir.", "en": "It consists of two naves, which are placed on one foot and positioned parallel to the qibla wall formed by two arches."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "Kendi türündeki mahalle mescitlerinden daha özenli bir plana ve taş işçiliğine sahip olan cami, düz tavan üzerine kırma çatılıdır.", "en": "The mosque, which has a more meticulous plan and stonework than the neighborhood mosques of its kind, has a hipped roof on a flat ceiling."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "Caminin kuzey ve güneyde dörder, batıda da iki tane olmak üzere toplam on penceresi vardır.", "en": "The mosque has a total of ten windows, four in the north and south and two in the west."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "Pencereler yuvarlak kemerleri ile dikkat çekmektedir.", "en": "The windows attract attention with their round arches."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "Doğu tarafta ise pencere yoktur.", "en": "There is no window on the east side."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "Güneye bakan çeşme aynasındaki altı satırlık kitabesine göre 1909 yılında yapılmıştır.", "en": "It was built in 1909, according to its six-line inscription on the south-facing fountain mirror."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "Düzgün işçilikle yapılmış, herhangi bir tezyinatı bulunmayan şadırvanın ahşap örtüsü doğrudan doğruya on kenarlı hazne üzerinde yükselen ahşap ayaklara oturmaktadır.", "en": "The wooden cover of the shadirvan, which was made with proper workmanship and has no decorations, rests directly on the wooden legs rising on the ten-sided chamber."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}, {"metin": {"tr": "Vakıflar Genel Müdürlüğü tarafından 1997 senesindeki onarımda cami ile birlikte şadırvanın ahşap örtüsü de yenilenmiş, taşlar zımparalanarak temizlenmiştir.", "en": "During the repair in 1997 by the General Directorate of Foundations, the wooden cover of the fountain was renewed along with the mosque, and the stones were cleaned by sanding."}, "kategori": "vakif", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "212-217"}], "gorseller": [{"dosya": "/gorseller/hatay/ahmediye-camii-hatay/03.webp", "alt": {"tr": "Ahmediye Camii, fotoğraf 3", "en": "Ahmediye Mosque, photo 3"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}, {"dosya": "/gorseller/hatay/ahmediye-camii-hatay/01.webp", "alt": {"tr": "Ahmediye Camii, fotoğraf 1", "en": "Ahmediye Mosque, photo 1"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}, {"dosya": "/gorseller/hatay/ahmediye-camii-hatay/02.webp", "alt": {"tr": "Ahmediye Camii, fotoğraf 2", "en": "Ahmediye Mosque, photo 2"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}, {"dosya": "/gorseller/hatay/ahmediye-camii-hatay/04.webp", "alt": {"tr": "Ahmediye Camii, fotoğraf 4", "en": "Ahmediye Mosque, photo 4"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}], "banisi": "Ahmed Bey", "mimari": {"onarimlar": [{"yil": 1941, "aciklama": {"tr": "Yuvarlak gövdeli minare eklendi.", "en": "A cylindrical minaret was added."}, "kaynak_id": "vk-hatay-envanter"}]}}'::jsonb, 'incelemede', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'ahmediye-camii-hatay' and durum = 'yayinda'), 'vk-hatay-envanter', '212-217', 'Bânî adı ve 1941 minare eklemesi künyeye işlendi.', 'Elif Şahin', now() - interval '20 hours') returning id into sid;
    values ('kaynak', 'surum', sid, 'ahmediye-camii-hatay', 'demo', 'tamam', '{"sonuc": "destekliyor", "sayfa": null, "pasaj": "1941 yılında, Hatay’ın ana vatana kavuşmasından hemen sonra âdeta zafer nişanesi olarak yapıya eklenen yuvarlak gövdeli narin minare, harimin güney batısında bulunur.", "kaynaktaki_deger": "1941 yılında ... yuvarlak gövdeli narin minare", "aciklama": "Minarenin 1941''de eklendiği kaynakta geçiyor. Bânî Ahmed Bey''in adı da kaynakta var.", "guven": "yuksek", "metin": "tamam", "pasaj_dogrulandi": true, "bulunan_sayfa": null, "sayfali": true, "kaynak_adresi": "https://www.vakifkatilim.com.tr/documents/KurumsalIletisim/hatay-vakif-eserleri.pdf", "incelenen_sayfalar": []}'::jsonb, 'gemini-flash-lite-latest', 'Sistem', now() - interval '19.5 hours', now() - interval '19.5 hours') returning id into aid;
  -- affan-ertugrul-camii-hatay (incelemede)
    values ('affan-ertugrul-camii-hatay', 'hatay', '{"id": "affan-ertugrul-camii-hatay", "ad": {"tr": "Affan (Ertuğrul) Camii", "en": "Affan (Ertuğrul) Mosque"}, "tur": "cami", "ilce": "Antakya", "donem": {"yapim_yili": 1894, "kaynak_id": "vk-hatay-envanter", "sayfa": "198-205", "yapim_yili_hicri": 1312}, "konum": {"enlem": 36.2025, "boylam": 36.1605, "dogrulandi": false, "yontem": "geocoding", "hassasiyet": "ilce"}, "envanter": {"kaynak_id": "vk-hatay-envanter", "sayfa": "198"}, "olgular": [{"metin": {"tr": "Affan ve Ertuğrul adlarıyla bilinen cami, üç tarafı sokakla çevrili, yatay, dikdörtgen alan üzerindeki tek mekânlı sade ve mütevazi görünümüyle Antakya’nın en eski mahalleleri arasında bir Osmanlı eseridir.", "en": "Affan and Ertuğrul, the mosque is a new Ottoman work among the oldest neighborhoods of Antakya with its plain and modest appearance, with a single space on a horizontal, rectangular area surrounded by streets on three sides."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "198-205"}, {"metin": {"tr": "II. Abdülhamid’in tuğrasının taçlandırdığı caminin kitabesinden, mabedin 1894/95 tarihinde yapıldığı anlaşılıyor.", "en": "The inscription on the mosque, crowned by Abdulhamid II’s signature (tughra), indicates that the temple was built in 1894/95. The mosque, which was built by a philanthropist named Affan, is also known as Ertuğrul."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "198-205"}, {"metin": {"tr": "Affan isminde bir hayırseverin bina ettirdiği caminin aynı zamanda adının Ertuğrul adıyla da anılmasının sebebi, Sultan Abdülhamid’in köklerine özlemin ve saygının bir hatırası olarak yorumlanmaktadır.", "en": "It is interpreted as a symbol of longing and respect for the roots of Sultan Abdülhamid."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "198-205"}, {"metin": {"tr": "Cami, evlerin ve diğer sivil yapıların arasına sıkışmış küçük ve süslemenin uygulanmadığı bir mimariye sahiptir.", "en": "The mosque has a small and unadorned architecture tucked between houses and other civilian structures."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "198-205"}, {"metin": {"tr": "Sade iki kapı ile küçük bir avluya girilmektedir.", "en": "A small courtyard is approached through two plain doors."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "198-205"}, {"metin": {"tr": "Avludan sonra ise tuğralı kitabenin altındaki bir kapıdan girilen dikdörtgen planlı, ahşap düz tavanlı yine küçük fakat huzurlu bir harime ulaşılmaktadır.", "en": "After the courtyard, a small but hidden sanctuary (harim) with a messy plan and a wooden flat ceiling is accessed through a door inside the inscription with the monogram."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "198-205"}, {"metin": {"tr": "Kıbleyi işaret eden mütevazı bir mihrap, onun sağında sade ve gösterişsiz ahşap bir minber, mihrabın bulunduğu duvarda bir, yan duvarlarında ise karşılıklı birer pencere ile aydınlanan ve Hızır Peygamberin hatırasına yapılmış bir makam yer alır.", "en": "A modest mihrab pointing to the qibla, a plain and unpretentious wooden pulpit to its right, and a maqam built in memory of the Prophet Khidr, illuminated by one window on the wall where the mihrab is located, and a window facing each other on the side walls."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "198-205"}, {"metin": {"tr": "Cami avlusunun güneyine bakan duvarında 1926 yılında inşa edilen ve düzgün kesme taşlarla yapılmış, susayanlara su veren çeşme, avlunun ortasındaki şadırvan ve cami kapısında iki satırlık kelime-i tevhid yazısı ile dikkati çeken yuvarlak gövdeli minare, burada bir mabedin varlığını uzaktakilere hissettirmektedir.", "en": "The fountain, which was built in 1926 on the wall facing the south of the mosque courtyard and made with smooth cut stones, gives water to those who are thirsty. The shadirvan in the middle of the courtyard and the minaret with a round body draw attention with the two-line “kelime-i tevhid” writing on the door of the mosque, makes the presence of a temple here felt to those far away."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "198-205"}, {"metin": {"tr": "Caminin tavanı, 1995 yılında yapılan onarımda hasır örgü ile kaplanmış ve aynı teknik, harimin duvarlarında da uygulanmıştır.", "en": "The ceiling of the mosque was covered with wicker-wave technique in the repair made in 1995 and the same technique was applied on the walls of the sanctuary (harim)."}, "kategori": "onarim", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "198-205"}, {"metin": {"tr": "2008 yılında Hatay Vakıflar Bölge Müdürlüğü tarafından restorasyonu gerçekleştirilmiştir.", "en": "It was restored by Hatay Foundations Regional Directorate in 2008."}, "kategori": "vakif", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "198-205"}, {"metin": {"tr": "Affan (Ertuğrul) Camii, Antakya gibi sade, fakat asude bir mekândır.", "en": "Affan (Ertuğrul) Mosque, like Antakya, is a simple yet peaceful place."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "198-205"}], "gorseller": [{"dosya": "/gorseller/hatay/affan-ertugrul-camii-hatay/01.webp", "alt": {"tr": "Affan (Ertuğrul) Camii, fotoğraf 1", "en": "Affan (Ertuğrul) Mosque, photo 1"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}, {"dosya": "/gorseller/hatay/affan-ertugrul-camii-hatay/02.webp", "alt": {"tr": "Affan (Ertuğrul) Camii, fotoğraf 2", "en": "Affan (Ertuğrul) Mosque, photo 2"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}, {"dosya": "/gorseller/hatay/affan-ertugrul-camii-hatay/03.webp", "alt": {"tr": "Affan (Ertuğrul) Camii, fotoğraf 3", "en": "Affan (Ertuğrul) Mosque, photo 3"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}, {"dosya": "/gorseller/hatay/affan-ertugrul-camii-hatay/04.webp", "alt": {"tr": "Affan (Ertuğrul) Camii, fotoğraf 4", "en": "Affan (Ertuğrul) Mosque, photo 4"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}], "banisi": "Affan (hayırsever)"}'::jsonb, 'incelemede', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'affan-ertugrul-camii-hatay' and durum = 'yayinda'), 'vk-hatay-envanter', '198-205', 'Kitâbeye göre yapım yılı ve bânî.', 'Elif Şahin', now() - interval '14 hours') returning id into sid;
    values ('kaynak', 'surum', sid, 'affan-ertugrul-camii-hatay', 'demo', 'tamam', '{"sonuc": "destekliyor", "sayfa": null, "pasaj": "II. Abdülhamid’in tuğrasının taçlandırdığı caminin kitabesinden, mabedin 1894/95 tarihinde yapıldığı anlaşılıyor.", "kaynaktaki_deger": "1894/95", "aciklama": "Kaynak kitâbeye dayanarak 1894/95 diyor; seçilen yıl uyumlu.", "guven": "yuksek", "metin": "tamam", "pasaj_dogrulandi": true, "bulunan_sayfa": null, "sayfali": true, "kaynak_adresi": "https://www.vakifkatilim.com.tr/documents/KurumsalIletisim/hatay-vakif-eserleri.pdf", "incelenen_sayfalar": []}'::jsonb, 'gemini-flash-lite-latest', 'Sistem', now() - interval '13.5 hours', now() - interval '13.5 hours') returning id into aid;
  -- sati-fakih-camii (incelemede)
    values ('sati-fakih-camii', 'bursa', '{"id": "sati-fakih-camii", "ad": {"tr": "Satı Fakih Camii ve Haziresi", "en": "Satı Fakih Mosque and Graveyard"}, "tur": "cami", "ilce": "Osmangazi", "adres": {"tr": "Mollagürani Mahallesi, Oruçbey Caddesi, No: 26, Osmangazi, Bursa", "en": "Mollagürani Neighborhood, Oruçbey Street, No. 26, Osmangazi, Bursa"}, "donem": {"yapim_yili": 1426, "yaklasik": true, "metin": {"tr": "1426-1430 arası (tahmin)", "en": "Between 1426 and 1430 (estimated)"}}, "banisi": "Satı Fakih", "tarihce": {"tr": "Osmangazi ilçesi, Mollagürani Mahallesi, Oruçbey Caddesi, No: 26’da yer almaktadır.\n\nCami, Sultan II. Murad ve Fâtih Sultan Mehmed dönemi hocalarından Satı Fakih tarafından inşa ettirilmiştir. Yapının ismi kaynaklarda farklı şekillerde yazılmış olsa da asıl adı (Sait, Sadi, Sa’d, Sa’dî) Satı Fakih’tir. Babasının Bayram Bey olduğu ve 1426 yılında hayatta bulunduğu arşiv kayıtlarında yer almaktadır. Oğlu Murad Fakih, babasının yaptırdığı bu camide imamlık yapmıştır.\n\nBelgelerde, Satı Fakih adıyla anılan bir mahallenin bulunduğu belirtilmektedir. Caminin bahçesinde Satı Fakih’e ait bir türbe yer almakta, ancak mezar taşı günümüze ulaşmadığı için kesin vefat tarihi bilinmemekte, yapının 1426-1430 yılları arasında inşa edildiği tahmin edilmektedir.\n\nCami sağlam vaziyettedir ve ibadete açıktır.", "en": "The mosque is located in Osmangazi District, Mollagürani Neighborhood, Oruçbey Street, No. 26.\n\nThe mosque was built by Satı Fakih, one of the teachers of the reign of Sultan Murad II and Fâtih Sultan Mehmed. Although the name of the building is written in different ways in the sources, its real name is (Sait, Sadi, Sa’d, Sa’dî) Satı Fakih. It is stated in the archive records that his father was Bayram Bey and that he was alive in 1426. His son, Murad Fakih, served as imam in this mosque built by his father.\n\nIt is stated in the documents that there was a neighborhood called Satı Fakih. There is a tomb belonging to Satı Fakih in the garden of the mosque, but since his gravestone has not survived to the present day, the exact date of his death is unknown, and it is presumed that the building was built between 1426-1430.\n\nThe mosque is in good condition today and is open for worship."}, "mimari": {"metin": {"tr": "Dikdörtgen planlı olan cami 6.30 × 9.90 m ölçülerindedir. Moloz taş duvarlarla inşa edilmiş, ahşap çatı ile örtülmüş ve kiremit kaplanmıştır. Günümüzde belirgin bir mimari özelliği bulunmamaktadır. Caminin bahçesinde, Satı Fakih’in türbesinin yanı sıra bir hazire de mevcuttur.\n\nHazire, caminin bahçesinde yer almaktadır.\n\nCaminin bahçesinde kendisine ait bir türbe yer almaktadır, ancak mezar taşı günümüze ulaşmamıştır.\n\nHazirede 19. yüzyıla ait mezar taşları bulunmaktadır. Taşları günümüze ulaşan kişiler arasında Dîvân-ı Hümâyun hâcegânından Seyyid Hacı Ali Efendi, Bedeviyye Şeyhi Seyyid Şeyh Osman Efendi, Mustafa Muhtar, Şerife Şakire Hanım, Seyyid Ali Fehim Efendi ve Şerife Hatice Hatun yer almaktadır.\n\nBunun dışında, Rumeli kazaskeri olan ve aynı zamanda bir mevlit yazdığı bilinen Mehmed Dede Efendi’nin (v. H. 1147 / M. 1735) de hazireye defnedildiği kayıtlarda geçmektedir.", "en": "The mosque has a rectangular plan and measures 6.30 × 9.90 m. It is built with rubble stone walls, and covered with a wooden roof covered with tiles. Today, it has no distinctive architectural features. In the garden of the mosque, there is a graveyard as well as the tomb of Satı Fakih.\n\nThe graveyard is located in the garden of the mosque.\n\nThere is a tomb belonging to Satı Fakih in the garden of the mosque, but his gravestone has not survived to the present day.\n\nThere are 19th century gravestones in the graveyard. Among the people whose stones have survived to the present day are Seyyid Hacı Ali Efendi from the hâcegân (masters) of the Dîvân-ı Hümâyun (Imperial Council), Seyyid Şeyh Osman Efendi, Mustafa Muhtar, Şerife Şakire Hanım, Seyyid Ali Fehim Efendi and Şerife Hatice Hatun.\n\nApart from this, it is recorded in the records that Mehmed Dede Efendi (d. AH 1147 / AD 1735), who was a Rumeli kazasker and is also known to have written a mevlid, was buried in the graveyard."}, "plan": "Dikdörtgen plan", "ust_ortu": "Kiremit kaplı ahşap çatı", "malzeme": ["moloz taş", "ahşap", "kiremit"]}, "olgular": [{"metin": {"tr": "Cami, Sultan II. Murad ve Fâtih Sultan Mehmed dönemi hocalarından Satı Fakih tarafından inşa ettirilmiştir.", "en": "The mosque was built by Satı Fakih, one of the teachers of the reign of Sultan Murad II and Fâtih Sultan Mehmed."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "410"}, {"metin": {"tr": "Satı Fakih’in oğlu Murad Fakih, babasının yaptırdığı bu camide imamlık yapmıştır.", "en": "His son, Murad Fakih, served as imam in this mosque built by his father."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "410"}, {"metin": {"tr": "Yapının 1426-1430 yılları arasında inşa edildiği tahmin edilmektedir.", "en": "It is presumed that the building was built between 1426-1430."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "410"}, {"metin": {"tr": "Dikdörtgen planlı cami 6.30 × 9.90 m ölçülerinde olup moloz taş duvarlarla inşa edilmiştir.", "en": "The mosque has a rectangular plan, measures 6.30 × 9.90 m and is built with rubble stone walls."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "410"}, {"metin": {"tr": "Caminin bahçesinde Satı Fakih’in türbesi ve bir hazire bulunmaktadır.", "en": "In the garden of the mosque there is a graveyard as well as the tomb of Satı Fakih."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "411"}, {"metin": {"tr": "Cami sağlam vaziyettedir ve ibadete açıktır.", "en": "The mosque is in good condition today and is open for worship."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "410"}, {"metin": {"tr": "Hazirede 19. yüzyıla ait mezar taşları bulunmaktadır.", "en": "There are 19th century gravestones in the graveyard."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "411"}], "envanter": {"kaynak_id": "vk-bursa-envanter-c1", "sayfa": "410-411"}, "konum": {"enlem": 40.184153, "boylam": 29.05547, "dogrulandi": false, "yontem": "geocoding", "hassasiyet": "mahalle"}, "gorseller": [{"dosya": "/gorseller/bursa/sati-fakih-camii/01.webp", "alt": {"tr": "Kiremit çatılı evler arasında cami ve minaresi", "en": "The mosque and minaret among tiled-roof houses"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/sati-fakih-camii/02.webp", "alt": {"tr": "Turkuaz halılı iç mekân, mihrap ve minber", "en": "Turquoise-carpeted interior with mihrab and minbar"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/sati-fakih-camii/03.webp", "alt": {"tr": "Renkli evlerle çevrili sokakta tuğla cami", "en": "Brick mosque on a street lined with colourful houses"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/sati-fakih-camii/04.webp", "alt": {"tr": "Ağaç altındaki hazirede eski mezar taşları", "en": "Old gravestones under a tree in the graveyard"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/sati-fakih-camii/05.webp", "alt": {"tr": "Bahçede bitkiler arasında bir sanduka", "en": "A cenotaph among plants in the garden"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/sati-fakih-camii/06.webp", "alt": {"tr": "Caminin ve çevresindeki çatıların kuşbakışı görünümü", "en": "Bird''s-eye view of the mosque and surrounding roofs"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}]}'::jsonb, 'incelemede', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'sati-fakih-camii' and durum = 'yayinda'), 'vk-bursa-envanter-c1', '410', 'Yapım aralığı künyeye eklendi.', 'Burak Öztürk', now() - interval '9 hours') returning id into sid;
    values ('kaynak', 'surum', sid, 'sati-fakih-camii', 'demo', 'tamam', '{"sonuc": "destekliyor", "sayfa": 410, "pasaj": "Yapının 1426-1430 yılları arasında inşa edildiği tahmin edilmektedir.", "kaynaktaki_deger": "1426-1430 yılları arası (tahmin)", "aciklama": "Kaynak tahmini bir aralık veriyor; ''yaklaşık'' işaretlenmiş, uygun.", "guven": "orta", "metin": "tamam", "pasaj_dogrulandi": true, "bulunan_sayfa": 410, "sayfali": true, "kaynak_adresi": "https://www.vakifkatilim.com.tr/documents/KurumsalIletisim/yayinlarimiz/bursa-envanteri-cilt-1.pdf", "incelenen_sayfalar": [409, 410, 411]}'::jsonb, 'gemini-flash-lite-latest', 'Sistem', now() - interval '8.5 hours', now() - interval '8.5 hours') returning id into aid;
  -- komurculer-camii-konya (incelemede)
    values ('komurculer-camii-konya', 'konya', '{"id": "komurculer-camii-konya", "ad": {"tr": "Kömürcüler Camii", "en": "Kömürcüler Mosque"}, "tur": "cami", "ilce": "Meram", "adres": {"tr": "Cami Meram İlçesi, Uluğbey Mahallesi, Gazezler Sokak, No. 13’te yer almaktadır.", "en": "The mosque is located in Meram District, Uluğbey Neighborhood, Gazezler Street No: 13. There is no information about the founder and history of the building."}, "konum": {"enlem": 37.83649, "boylam": 32.495587, "dogrulandi": false, "yontem": "geocoding", "hassasiyet": "mahalle"}, "envanter": {"kaynak_id": "vk-konya-envanter-c1", "sayfa": "82"}, "olgular": [{"metin": {"tr": "Cami Meram İlçesi, Uluğbey Mahallesi, Gazezler Sokak, No. 13’te yer almaktadır.", "en": "The mosque is located in Meram District, Uluğbey Neighborhood, Gazezler Street No: 13. There is no information about the founder and history of the building."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "82"}, {"metin": {"tr": "Yapının bânîsi ve tarihi ile ilgili hiçbir bilgi mevcut değildir. Orijinalinde son dönem Osmanlı eseridir. 1990’lı yıllarda taşınarak günümüzdeki hâlini almıştır.", "en": "It is originally a late Ottoman work. It was relocated in the 1990s and took its current form."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "82"}, {"metin": {"tr": "Cami kare planlı ve tek kubbelidir.", "en": "The mosque has a square plan and a single dome."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "82"}, {"metin": {"tr": "Üzeri dıştan kırma çatıyla örtülüdür.", "en": "It is covered with a hipped roof from the outside."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "82"}, {"metin": {"tr": "İnşasında taş ve tuğla malzeme kullanılmıştır.", "en": "Stone and brick materials were used in its construction."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "82"}, {"metin": {"tr": "Cami cephelerinde aynı boyutlarda, iki katlı, düz lentolu pencereler vardır.", "en": "On the facades of the mosque there are two-layered windows of the same size, with flat lintels."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "82"}, {"metin": {"tr": "Kubbe kasnağındaki kalem işi süslemeler Cumhuriyet dönemi özelliklerini taşımaktadır.", "en": "The hand-carved decorations on the dome drum bear the characteristics of the Republic period."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "82"}], "gorseller": [{"dosya": "/gorseller/konya/komurculer-camii-konya/02.webp", "alt": {"tr": "Kömürcüler Camii, fotoğraf 2", "en": "Kömürcüler Mosque, photo 2"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Konya Vakıf Eserleri Envanteri", "kaynak_id": "vk-konya-envanter-c1"}, {"dosya": "/gorseller/konya/komurculer-camii-konya/01.webp", "alt": {"tr": "Kömürcüler Camii, fotoğraf 1", "en": "Kömürcüler Mosque, photo 1"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Konya Vakıf Eserleri Envanteri", "kaynak_id": "vk-konya-envanter-c1"}], "banisi": "Hacı Mehmed Efendi"}'::jsonb, 'incelemede', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'komurculer-camii-konya' and durum = 'yayinda'), 'demo-konya-salname', '112', 'Salnamede geçen bânî adı eklendi.', 'Burak Öztürk', now() - interval '6 hours') returning id into sid;
    values ('kaynak', 'surum', sid, 'komurculer-camii-konya', 'demo', 'tamam', '{"metin": "kaynak_yok", "aciklama": "Seçilen kaynağın (salname kaydı) dijital kopyası yüklenmemiş; yapay zekâ karşılaştırma yapamadı. Envanter kitabı bânî için ''hiçbir bilgi mevcut değildir'' diyor."}'::jsonb, 'gemini-flash-lite-latest', 'Sistem', now() - interval '5.5 hours', now() - interval '5.5 hours') returning id into aid;
  -- selcuk-hatun-camii (incelemede)
    values ('selcuk-hatun-camii', 'bursa', '{"id": "selcuk-hatun-camii", "ad": {"tr": "Selçuk Hatun Camii", "en": "Selçuk Hatun Mosque"}, "tur": "cami", "ilce": "Osmangazi", "adres": {"tr": "Kayhan Mahallesi, Selçuk Hatun Sokak, No: 1, Osmangazi, Bursa", "en": "Kayhan Neighborhood, Selçuk Hatun Street, No. 1, Osmangazi, Bursa"}, "donem": {"yapim_yili": 1455, "yapim_yili_hicri": 854}, "banisi": "Selçuk Hatun", "tarihce": {"tr": "Osmangazi ilçesi, Kayhan Mahallesi, Selçuk Hatun Sokak, No:1’de yer almaktadır. Cami, Sultan Çelebi Mehmed’in kızı Selçuk Hatun tarafından H. 854 / M. 1450 yılında inşa ettirilmiştir. Giriş kapısı üzerinde, mermer üzerine sülüs hat ile yazılmış bir kitabe bulunmaktadır.\n\nKitabede şu ifadeler yer almaktadır: “Emaret bi-imâret-i hâzâ’l-mescidi’ş-şerîf Selçuk Hâtun bint-i es-Sultân ibni’s-Sultân es-Sultân Mehmed bin Bâyezîd Gâzî Hân halledallâhü memleketehû ve ebbede devletehû ve şevketehû fî âhir-i şehr-i Ramazane’l-mu’azzam Hicreti’n-Nebiyyi aleyhi’s-salâvâtü ve’s-selâm min şühûri seneti erba’a ve hamsîne ve semâne mi’e.”\n\nMealen: “Bu şerefli mescidin inşasını, Gazi Sultan Bayezid Han’ın oğlu Sultan Mehmed’in kızı Selçuk Hatun, -Allah memleketini daim, devletini ve kudretini ebedî kılsın-, Hicrî 854 yılının Ramazan ayının sonlarında (Ekim 1450) emretmiştir.”\n\nSelçuk Hatun 1407 senesinde Amasya’da doğmuştur. 1425 yılında 18 yaşında Osmanoğulları ve Candaroğulları ittifakının pekiştirilmesi amacıyla Candaroğlu İbrahim Bey ile evlendirilmiştir. Gelin olarak beyliğin merkezi olan Kastamonu’ya gitmiştir. Bir müddet sonra eşi İbrahim Bey beyliğin başına geçmiş, ancak dört sene sonra eşinin vefat etmesi üzerine Bursa’ya dönmüştür.\n\nBursa’ya geldikten sonra kendini hayır işlerine veren Selçuk Hatun’un şehirde inşa ettirdiği mescidi, zaviyesi, imareti ve bir köprüsü dışında Edirne ve İstanbul’da birer mescidi daha bulunmaktadır. Kastamonu’da vefat eden çocukları için de türbe yaptırmıştır. 25 Ekim 1485 tarihinde vefat etmiş ve Bursa’daki Yeşil Türbe’de, babasının yanına defnedilmiştir.\n\nSelçuk Hatun, Bursa’daki camisine, ağabeyi II. Murad’ın, yeğeni Fâtih Sultan Mehmed’in ve torun-yeğeni II. Bayezid’in temlik ettiği, ayrıca kendisinin satın aldığı Manyas, Ulubad, Karacabey, Kite ve Soğanlık’taki köy, çiftlik ve araziler ile Bursa’daki ev, dükkân, bağ ve bahçelerinin tamamını vakfetmiştir. Vakıflar Genel Müdürlüğü Arşivi’nde yer alan vakfiye kopyasında vakıfların detayları bulunmaktadır.", "en": "The mosque is located in Osmangazi District, Kayhan Neighborhood, Selçuk Hatun Street, No. 1. The mosque was built by Selçuk Hatun, the daughter of Sultan Çelebi Mehmed, in AH 854 / AD 1450. There is an inscription written in Thuluth calligraphy on marble above the entrance door.\n\nThe inscription includes the following statements: “Emaret bi-imâret-i hâzâ’l-mescidi’ş-şerîf Selçuk Hâtun bint-i es-Sultân ibni’s-Sultân es-Sultân Mehmed bin Bâyezîd Gâzî Hân halledallâhü memleketehû ve ebbede devletehû ve şevketehû fî âhir-i şehr-i Ramazane’l-mu’azzam Hicreti’n-Nebiyyi aleyhi’s-salâvâtü ve’s-selâm min şühûri seneti erba’a ve hamsîne ve semâne mi’e.”\n\nMeaning: “The construction of this honorable mosque was ordered by Seljuk Hatun, the daughter of Sultan Mehmed, the son of Gazi Sultan Bayezid Han -may Allah make his country permanent, his state and his power eternal- at the end of the month of Ramadan in the year 854 Hijri (October 1450).”\n\nSelçuk Hatun was born in Amasya in 1407. In 1425, at the age of 18, she was married to Candaroğlu İbrahim Bey in order to strengthen the alliance of the Osmanoğulları and Candaroğulları. As a bride, she went to Kastamonu, the center of the principality. After a while, her husband, İbrahim Bey, became the head of the principality, but after he died four years later, she returned to Bursa. Selçuk Hatun, who devoted herself to charity work after coming to Bursa, had a mosque, a zawiya, an imaret and a bridge built in the city, as well as two other masjids in Edirne and Istanbul. She also had a tomb built for her deceased children in Kastamonu.\n\nSelçuk Hatun died on October 25, 1485 and was buried next to her father in the Yeşil Tomb in Bursa.\n\nSelçuk Hatun endowed all of the villages, farms and lands in Manyas, Ulubad, Karacabey, Kite and Soğanlık alongside her houses, shops, vineyards and gardens in Bursa, which her brother Murad II, her nephew Fâtih Sultan Mehmed and her great nephew Bayezid II had assigned, and which she acquired, to her mosque in Bursa. Details of the foundations are included in the endowment charter copy in the General Directorate of Foundations Archive."}, "mimari": {"metin": {"tr": "Bursa’da inşa ettirdiği ve kendi adıyla anılan Selçuk Hatun Camii, tek kubbeli asıl ibadet mekânı ile kuzey yönündeki üç bölümlü son cemaat yerinden oluşmaktadır. Ana ibadet mekânı, 8.80 × 8.80 m ölçülerinde, kare planlıdır. Üzeri, dıştan sekizgen bir kasnağa, içten ise prizmatik üçgen motifli bir kuşağa oturan kurşun kaplı bir kubbe ile örtülüdür.\n\nSon cemaat yeri, 3.10 × 8.80 m ölçülerindedir. Kalkan duvarlı ve üç gözlü olarak düzenlenmiştir. Ortası yarım daire kesitli bir tonozla, yanlardaki bölümler ise düz tavanla örtülüdür. Mekânın ortasında yer alan iki yığma ayak ile yan duvarları birbirine bağlayan üç sivri kemerden ortada olanının altında Bursa kemeri bulunmaktadır. İki kemerin arası, altıgen taşlar ve lacivert çinilerle süslenmiştir. Caminin kalkan duvarı ve doğu, batı, güney duvarlarında bulunan kör kemerlerin içi, tuğladan çeşitli motiflerle bezenmiştir. Yapının duvarları, iki sıra tuğla ve bir sıra moloz taş ile örülmüştür.\n\nCaminin kuzeybatı köşesinde yer alan sekizgen kaideli minare, silindirik gövdeli ve sivri külahlıdır. Minareye giriş son cemaat yerinden sağlanmaktadır.\n\nCami, zaman içinde birçok kez onarım görmüştür. 1950’li yıllara gelindiğinde caminin yalnızca bir ahşap revakı kalmış, buna karşın duvarları ve kubbesi sağlamlığını korumuştur. 1966 yılında Eski Eserleri Sevenler Kurumu tarafından revak yenilenmiş ve yapı genel bir onarımdan geçirilmiştir. Bir yıl sonra, caminin batı tarafındaki çeşmeler de restore edilmiştir.\n\nAvlunun köşesinde sokağa cepheli iki yüzlü bir çeşme bulunmaktadır. Bahçesinde de bazı mezar taşları yer almaktadır.\n\nCami son derece bakımlı durumdadır ve ibadete açıktır.", "en": "The Selçuk Hatun Mosque, which she had built in Bursa and is named after her, consists of a single-domed main prayer hall and a three-part narthex to the north. The main prayer hall has a square plan, measuring 8.80 × 8.80 m. It is covered with a lead-coated dome, which sits on an octagonal drum on the outside and on a band with prismatic triangle motifs on the inside.\n\nThe narthex measures 3.10 × 8.80 m. It is designed with a parapet wall and has three bays. The middle part is covered with a semicircular vault, and the side sections are covered with a flat ceiling. There is a Bursa arch under the middle one of the three pointed arches connecting the two piers in the middle of the space and the side walls. The space between the two arches is decorated with hexagonal stones and dark blue tiles. The inside of the blind arches on the parapet wall and the east, west and south walls of the mosque are decorated with various brick motifs. The walls of the building are built with two rows of bricks and one row of rubble stones.\n\nThe octagonal-based minaret, located in the northwest corner of the mosque, has a cylindrical shaft and a pointed spire. The entrance to the minaret is provided from the narthex.\n\nThe mosque has been repaired many times over time. By the 1950s, only a wooden portico remained of the mosque, but its walls and dome remained intact. In 1966, the portico was renovated by the Association for the Appreciation of Antiquities and the building underwent a general restoration. A year later, the fountains on the west side of the mosque were also restored.\n\nThere is a two-sided fountain in the corner of the courtyard facing the street. There are also some gravestones in the garden.\n\nThe mosque is extremely well-maintained and is open for worship."}, "plan": "Kare plan", "ust_ortu": "Kurşun kaplı kubbe", "malzeme": ["tuğla", "moloz taş"], "onarimlar": [{"yil": 1966, "aciklama": {"tr": "Eski Eserleri Sevenler Kurumu tarafından revak yenilenmiş ve yapı genel bir onarımdan geçirilmiştir.", "en": "The portico was renovated by the Association for the Appreciation of Antiquities and the building underwent a general restoration."}, "kaynak_id": "vk-bursa-envanter-c1"}]}, "olgular": [{"metin": {"tr": "Cami, Sultan Çelebi Mehmed’in kızı Selçuk Hatun tarafından H. 854 / M. 1450 yılında inşa ettirilmiştir.", "en": "The mosque was built by Selçuk Hatun, the daughter of Sultan Çelebi Mehmed, in AH 854 / AD 1450."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "412"}, {"metin": {"tr": "Giriş kapısı üzerinde, mermer üzerine sülüs hat ile yazılmış bir kitabe bulunmaktadır.", "en": "There is an inscription written in Thuluth calligraphy on marble above the entrance door."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "412"}, {"metin": {"tr": "Selçuk Hatun 1425 yılında Candaroğlu İbrahim Bey ile evlendirilmiştir.", "en": "In 1425, Selçuk Hatun was married to Candaroğlu İbrahim Bey."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "413"}, {"metin": {"tr": "Selçuk Hatun 25 Ekim 1485 tarihinde vefat etmiş ve Bursa’daki Yeşil Türbe’de, babasının yanına defnedilmiştir.", "en": "Selçuk Hatun died on October 25, 1485 and was buried next to her father in the Yeşil Tomb in Bursa."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "413"}, {"metin": {"tr": "Selçuk Hatun, camisine Manyas, Ulubad, Karacabey, Kite ve Soğanlık’taki köy, çiftlik ve araziler ile Bursa’daki ev, dükkân, bağ ve bahçelerini vakfetmiştir.", "en": "Selçuk Hatun endowed the villages, farms and lands in Manyas, Ulubad, Karacabey, Kite and Soğanlık and her houses, shops, vineyards and gardens in Bursa to her mosque."}, "kategori": "vakif", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "413"}, {"metin": {"tr": "Ana ibadet mekânı 8.80 × 8.80 m ölçülerinde, kare planlıdır ve kurşun kaplı bir kubbe ile örtülüdür.", "en": "The main prayer hall has a square plan measuring 8.80 × 8.80 m and is covered with a lead-coated dome."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "414"}, {"metin": {"tr": "1966 yılında Eski Eserleri Sevenler Kurumu tarafından revak yenilenmiş ve yapı genel bir onarımdan geçirilmiştir.", "en": "In 1966, the portico was renovated by the Association for the Appreciation of Antiquities and the building underwent a general restoration."}, "kategori": "onarim", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "414"}, {"metin": {"tr": "Cami son derece bakımlı durumdadır ve ibadete açıktır.", "en": "The mosque is extremely well-maintained and is open for worship."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "414"}], "envanter": {"kaynak_id": "vk-bursa-envanter-c1", "sayfa": "412-414"}, "konum": {"enlem": 40.182325, "boylam": 29.06998, "dogrulandi": false, "yontem": "osm", "hassasiyet": "eser"}, "gorseller": [{"dosya": "/gorseller/bursa/selcuk-hatun-camii/01.webp", "alt": {"tr": "Ağaçlar arasında kubbeli tuğla cami ve minaresi", "en": "Domed brick mosque and minaret among trees"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/selcuk-hatun-camii/02.webp", "alt": {"tr": "Beyaz duvarlı, kırmızı halılı iç mekân", "en": "White-walled, red-carpeted interior"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/selcuk-hatun-camii/03.webp", "alt": {"tr": "Kubbenin ve minarenin kuşbakışı görünümü", "en": "Bird''s-eye view of the dome and minaret"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/selcuk-hatun-camii/04.webp", "alt": {"tr": "Mahalle içinde kubbeli cami, yukarıdan", "en": "The domed mosque in its neighbourhood, from above"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}]}'::jsonb, 'incelemede', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'selcuk-hatun-camii' and durum = 'yayinda'), 'vk-bursa-envanter-c1', '412', 'Yapım yılı düzeltildi.', 'Selin Aydın', now() - interval '3 hours') returning id into sid;
    values ('kaynak', 'surum', sid, 'selcuk-hatun-camii', 'demo', 'tamam', '{"sonuc": "celisiyor", "sayfa": 412, "pasaj": "Cami, Sultan Çelebi Mehmed’in kızı Selçuk Hatun tarafından H. 854 / M. 1450 yılında inşa ettirilmiştir.", "kaynaktaki_deger": "H. 854 / M. 1450", "aciklama": "Kaynak yapım yılını M. 1450 olarak veriyor; önerilen 1455 kaynakla çelişiyor.", "guven": "yuksek", "metin": "tamam", "pasaj_dogrulandi": true, "bulunan_sayfa": 412, "sayfali": true, "kaynak_adresi": "https://www.vakifkatilim.com.tr/documents/KurumsalIletisim/yayinlarimiz/bursa-envanteri-cilt-1.pdf", "incelenen_sayfalar": [411, 412, 413]}'::jsonb, 'gemini-flash-lite-latest', 'Sistem', now() - interval '2.5 hours', now() - interval '2.5 hours') returning id into aid;
  -- meydan-camii-ve-kulliyesi-hatay (editorde)
    values ('meydan-camii-ve-kulliyesi-hatay', 'hatay', '{"id": "meydan-camii-ve-kulliyesi-hatay", "ad": {"tr": "Meydan Camii ve Külliyesi", "en": "Meydan Mosque and Complex"}, "tur": "kulliye", "ilce": "Antakya", "donem": {"yaklasik": true, "metin": {"tr": "19. yüzyıl", "en": "19th century"}, "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}, "konum": {"enlem": 36.2025, "boylam": 36.1605, "dogrulandi": false, "yontem": "geocoding", "hassasiyet": "ilce"}, "envanter": {"kaynak_id": "vk-hatay-envanter", "sayfa": "121"}, "olgular": [{"metin": {"tr": "Meydan Camii Külliyesi’nin kesin yapılış tarihi bilinmemektedir. Yakınında bulunan ve aynı ismi taşıyan hamamın 1527 tarihli Osmanlı sayımında adı geçmesi sebebiyle eser, 16. yüzyıla tarihlenmek istenmektedir. Hakkında sahip olduğumuz kesin bilgi yapının 1878’de esaslı bir şekilde onarılmış olmasıdır.", "en": "The exact date of construction of the Meydan Mosque Complex is unknown. It is likely to date the work to the 16 th century, since the Turkish Bath with the same name, located nearby, was mentioned in the Ottoman census dated 1527. The exact information we have about it is that the building was extensively repaired in 1878."}, "kategori": "onarim", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}, {"metin": {"tr": "Eserin cami, şadırvan, medrese odaları ve muvakkithaneden meydana gelen tüm elemanları ortadaki avlunun içerisinde yer almaktadır.", "en": "All the elements of the work consisting of a mosque, shadirvan, madrasa rooms and a muvakkithane are located in the courtyard in the middle."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}, {"metin": {"tr": "Külliyeyi meydana getiren tüm yapılar taştan yapılmıştır.", "en": "All the structures that make up the complex are made of stone."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}, {"metin": {"tr": "Avluya giriş çıkışı sağlayan doğudaki kapı, hem beşik tonozlu, eyvan şeklinde düzenlenmiş olması hem de tepede yükselen yuvarlak gövdeli, şemsiye külahlı minaresi ile görenlerde derin bir hayranlık uyandırmaktadır.", "en": "The eastern door, which provides entrance and exit to the courtyard, arouses a deep admiration for those who see it, both with its barrel vaulted, iwan-like arrangement, and also with its minaret that has a round body and umbrella cone rising on the top."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}, {"metin": {"tr": "Minarenin eyvan üzerinde bulunan kapısına, avlunun içinde ihata duvarına paralel olarak yapılmış merdivenli bir rampayla ulaşılmaktadır.", "en": "The gate of the minaret on the iwan is reached through a ramp with stairs built parallel to the enclosing wall in the courtyard."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}, {"metin": {"tr": "Minare kapısının önündeki sahanlık, konsollar üzerine oturtulmuş bir balkon gibi çıkıntılıdır.", "en": "The landing in front of the minaret door is protruding like a balcony placed on consoles."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}, {"metin": {"tr": "Güneydoğu köşesinde medresenin iki odası ve bir dersliği, kuzeyinde medresenin diğer beş odası, kuzeybatıda da muvakkithane olarak yapılmış fakat günümüzde kitap satış yeri olarak kullanılan küçük bir mekân bulunmaktadır.", "en": "There are two rooms and a classroom of the madrasa in the southeast corner, the other five rooms of the madrasa in the north, and a small space in the northwest that was built as a muvakkithane but used as a book sales shop today."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}, {"metin": {"tr": "Düzgün dikdörtgen plan üzerine beyaz kesme taşlardan yapılmış olan harim, doğu-batı yönünde konumlanmıştır.", "en": "The sanctuary, made of white cut stones on a smooth rectangular plan, is located in the east-west direction."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}, {"metin": {"tr": "Mihrabın yapılan onarımlarla birlikte orijinal şeklini kaybettiği anlaşılmaktadır.", "en": "It is understood that the mihrab lost its original shape with the repairs."}, "kategori": "onarim", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}, {"metin": {"tr": "Günümüzde medresenin kuzeyinde beş, güneydoğusunda ise iki odası ve bir dersliği vardır.", "en": "Today, the madrasah has five rooms in the north and two rooms and a classroom in the southeast."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}, {"metin": {"tr": "Odaların her birisi avluya basık kemerli bir kapı ve iki pencere ile açıldığı halde, bunlardan daha büyük yapılmış olan derslik, çapraz tonoz örtülüdür.", "en": "Although each of the rooms opens to the courtyard with a low-arched door and two windows, the larger classroom is covered with cross vaults."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}, {"metin": {"tr": "Medresenin Habib-i Neccar, Ulu, Şeyh Ali, Yeni Cami medreselerine benzer özelliklere sahip olduğu dikkate alındığında, Meydan Cami Medresesi’nin de 19. yüzyılda inşa edilmiş olduğunu düşünmek mümkündür.", "en": "Considering that the madrasa has similar characteristics to the Habib-i Neccar, Grand, Sheikh Ali and New Mosque madrasas, it is possible to think that the Meydan Mosque Madrasa was built in the 19th century."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}, {"metin": {"tr": "1903 yılında faal olduğu bilinen medrese, 1878 ve 1985 yıllarında onarım görmüştür.", "en": "The madrasa, which was known to be active in 1903, was repaired in 1878 and 1985."}, "kategori": "onarim", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "121-138"}], "gorseller": [{"dosya": "/gorseller/hatay/meydan-camii-ve-kulliyesi-hatay/01.webp", "alt": {"tr": "Meydan Camii ve Külliyesi, fotoğraf 1", "en": "Meydan Mosque and Complex, photo 1"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}, {"dosya": "/gorseller/hatay/meydan-camii-ve-kulliyesi-hatay/02.webp", "alt": {"tr": "Meydan Camii ve Külliyesi, fotoğraf 2", "en": "Meydan Mosque and Complex, photo 2"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}, {"dosya": "/gorseller/hatay/meydan-camii-ve-kulliyesi-hatay/03.webp", "alt": {"tr": "Meydan Camii ve Külliyesi, fotoğraf 3", "en": "Meydan Mosque and Complex, photo 3"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}, {"dosya": "/gorseller/hatay/meydan-camii-ve-kulliyesi-hatay/04.webp", "alt": {"tr": "Meydan Camii ve Külliyesi, fotoğraf 4", "en": "Meydan Mosque and Complex, photo 4"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}], "mimari": {"malzeme": ["taş"]}}'::jsonb, 'editorde', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'meydan-camii-ve-kulliyesi-hatay' and durum = 'yayinda'), 'vk-hatay-envanter', '121-138', 'Malzeme bilgisi künyeye eklendi.', 'Elif Şahin', now() - interval '70 hours', 'Doç. Dr. Zeynep Arslan', now() - interval '22 hours', 'Kaynakla uyumlu, editöre gönderildi.') returning id into sid;
    values ('kaynak', 'surum', sid, 'meydan-camii-ve-kulliyesi-hatay', 'demo', 'tamam', '{"sonuc": "destekliyor", "sayfa": null, "pasaj": "Külliyeyi meydana getiren tüm yapılar taştan yapılmıştır.", "kaynaktaki_deger": "taş", "aciklama": "Kaynakta ''tüm yapılar taştan yapılmıştır'' yazıyor.", "guven": "yuksek", "metin": "tamam", "pasaj_dogrulandi": true, "bulunan_sayfa": null, "sayfali": true, "kaynak_adresi": "https://www.vakifkatilim.com.tr/documents/KurumsalIletisim/hatay-vakif-eserleri.pdf", "incelenen_sayfalar": []}'::jsonb, 'gemini-flash-lite-latest', 'Sistem', now() - interval '69.5 hours', now() - interval '69.5 hours') returning id into aid;
  -- seyh-ebul-vefa-camii-konya (editorde)
    values ('seyh-ebul-vefa-camii-konya', 'konya', '{"id": "seyh-ebul-vefa-camii-konya", "ad": {"tr": "Şeyh Ebul Vefa Camii", "en": "Şeyh Ebul Vefa Mosque"}, "tur": "cami", "ilce": "Meram", "adres": {"tr": "Cami Meram, Selam Mahallesi, Dere Caddesi, No. 28’de yer almaktadır.", "en": "The mosque is located at Meram District, Selam Neighborhood, Dere Str. No: 28. The mosque was built by Karamanoğlu İbrahim Bey in the name of Şeyh Vefa as a part of the social complex. The registration date of the social complex foundation is 869 AH / 1459 AD. The cemetery located in the east of the social complex was also removed later. In the 17th century, only Vefa Mosque and its surroundings in Meram were called Şeyh Vefa District. Over time, only the mosque part remained from the work, and this part was rebuilt in 1850, according to the inscription above the entrance door."}, "konum": {"enlem": 37.855117, "boylam": 32.420912, "dogrulandi": false, "yontem": "geocoding", "hassasiyet": "eser"}, "envanter": {"kaynak_id": "vk-konya-envanter-c1", "sayfa": "88"}, "olgular": [{"metin": {"tr": "Cami Meram, Selam Mahallesi, Dere Caddesi, No. 28’de yer almaktadır.", "en": "The mosque is located at Meram District, Selam Neighborhood, Dere Str. No: 28. The mosque was built by Karamanoğlu İbrahim Bey in the name of Şeyh Vefa as a part of the social complex. The registration date of the social complex foundation is 869 AH / 1459 AD. The cemetery located in the east of the social complex was also removed later. In the 17th century, only Vefa Mosque and its surroundings in Meram were called Şeyh Vefa District. Over time, only the mosque part remained from the work, and this part was rebuilt in 1850, according to the inscription above the entrance door."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "88"}, {"metin": {"tr": "Cami külliyenin bir parçası olarak Karamanoğlu İbrahim Bey tarafından Şeyh Vefa adına yaptırılmıştır. Külliye vakfiyesinin tescil tarihi ise H. 869 / M. 1459’dur. Külliyenin doğusunda bulunan kabristan da sonradan kaldırılmıştır.", "en": "The domed mosque, which has a rectangular plan almost square, was built of stone and brick. The dome is covered with a hipped roof from the outside. Two windows on the east, west and south facades illuminate the interior. A narthex was later added to the east side. A simply arranged mihrab can be seen in the middle of the qibla wall."}, "kategori": "vakif", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "88"}, {"metin": {"tr": "XVII. yüzyılda Meram’da sadece Vefa Camii ve çevresi Şeyh Vefa Mahallesi olarak anılmıştır. Zaman içinde eserden geriye sadece cami kısmı kalmış ve bu kısım da giriş kapısının üstündeki kitâbeye göre 1850 tarihinde yeniden inşa edilmiştir.", "en": "In the 17th century only the Vefa Mosque and its surroundings in Meram were known as the Şeyh Vefa Quarter. Over time only the mosque survived, and according to the inscription above its entrance it was rebuilt in 1850."}, "kategori": "onarim", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "88", "en_ceviri": "yz"}, {"metin": {"tr": "Kareye yakın dikdörtgen plana sahip kubbeli cami taş ve tuğla malzemeden inşa edilmiştir. Kubbe dıştan kırma çatıyla örtülmüştür. Doğu, batı ve güney cephelerinde ikişer adet pencere iç mekânı aydınlatmaktadır. Son cemaat yeri doğu tarafına sonradan eklenmiştir.  Kıble duvarının ortasında sade düzenlenmiş mihrap görülmektedir.", "en": "The domed mosque, nearly square in plan, is built of stone and brick. On the outside the dome is covered by a hipped roof. Two windows on each of the east, west and south façades light the interior. The narthex (last congregation area) on the east side was added later. A plainly designed mihrab stands in the middle of the qibla wall."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "88", "en_ceviri": "yz"}], "gorseller": [{"dosya": "/gorseller/konya/seyh-ebul-vefa-camii-konya/02.webp", "alt": {"tr": "Şeyh Ebul Vefa Camii, fotoğraf 2", "en": "Şeyh Ebul Vefa Mosque, photo 2"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Konya Vakıf Eserleri Envanteri", "kaynak_id": "vk-konya-envanter-c1"}, {"dosya": "/gorseller/konya/seyh-ebul-vefa-camii-konya/01.webp", "alt": {"tr": "Şeyh Ebul Vefa Camii, fotoğraf 1", "en": "Şeyh Ebul Vefa Mosque, photo 1"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Konya Vakıf Eserleri Envanteri", "kaynak_id": "vk-konya-envanter-c1"}], "banisi": "Karamanoğlu İbrahim Bey", "mimari": {"malzeme": ["taş", "tuğla"]}}'::jsonb, 'editorde', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'seyh-ebul-vefa-camii-konya' and durum = 'yayinda'), 'vk-konya-envanter-c1', '88', 'Bânî ve malzeme künyeye işlendi.', 'Selin Aydın', now() - interval '64 hours', 'Doç. Dr. Zeynep Arslan', now() - interval '18 hours', 'Bânî kaynakta açık. Malzemeyi ''taş ve tuğla'' olarak düzelterek gönderdim.') returning id into sid;
    values ('kaynak', 'surum', sid, 'seyh-ebul-vefa-camii-konya', 'demo', 'tamam', '{"sonuc": "destekliyor", "sayfa": 88, "pasaj": "Cami külliyenin bir parçası olarak Karamanoğlu İbrahim Bey tarafından Şeyh Vefa adına yaptırılmıştır. Külliye vakfiyesinin tescil tarihi ise H. 869 / M. 1459’dur. Külliyenin doğusunda bulunan kabristan da sonradan kaldırılmıştır.", "kaynaktaki_deger": "Karamanoğlu İbrahim Bey", "aciklama": "Bânî kaynaktaki cümleyle birebir aynı.", "guven": "yuksek", "metin": "tamam", "pasaj_dogrulandi": true, "bulunan_sayfa": 88, "sayfali": true, "kaynak_adresi": "https://www.vakifkatilim.com.tr/documents/KurumsalIletisim/yayinlarimiz/konya-envanteri-1_cilt-web.pdf", "incelenen_sayfalar": [87, 88, 89]}'::jsonb, 'gemini-flash-lite-latest', 'Sistem', now() - interval '63.5 hours', now() - interval '63.5 hours') returning id into aid;
  -- nalbantoglu-camii (editorde)
    values ('nalbantoglu-camii', 'bursa', '{"id": "nalbantoglu-camii", "ad": {"tr": "Nalbantoğlu Camii", "en": "Nalbantoğlu Mosque"}, "tur": "cami", "ilce": "Osmangazi", "adres": {"tr": "Nalbantoğlu Mahallesi, Nalbantoğlu Sokak, No: 2, Osmangazi, Bursa", "en": "Nalbantoğlu Neighborhood, Nalbantoğlu Street No. 2, Osmangazi, Bursa"}, "donem": {"yaklasik": true, "metin": {"tr": "Sultan II. Murad dönemi", "en": "reign of Sultan Murad II"}}, "banisi": "Nalbantbaşı", "tarihce": {"tr": "Osmangazi ilçesi, Nalbantoğlu Mahallesi, Nalbantoğlu Sokak No: 2 adresinde konumlanmaktadır. Yapı, Sultan II. Murad döneminde Nalbantbaşı tarafından mahalle mescidi olarak inşa ettirilmiş, 1777 yılında minber eklenerek camiye dönüştürülmüştür.\n\nTarihî kaynaklarda, caminin doğusunda -aynı adla anılan- bir sıbyan mektebinin bulunduğu belirtilmektedir. Mektebin haziresinde caminin imamı ve mektebin hocası Palancı Hoca Ömer Hulusi Efendi (v. H. 1293 / M. 1876), Bursa Kadısı Şâmîzâde Mustafa Efendi (v. H. 1194 / M. 1780) ve Nakibüleşraf Yörükzâde Mehmed Efendi’ye (ö. H. 1217 / M. 1802) ait mezarların yanı sıra başka şahıslara ait mezarların da bulunduğu ifade edilmektedir. Kayıtlarda uzun süre okul olarak kullanılan mektebin yıkılmasının ardından, mezarlardan kalan birkaç taşın Emir Sultan Mezarlığı’na götürüldüğü yer almaktadır.\n\nYapımından itibaren çeşitli doğal afetlerden zarar gören cami, 1518’deki yangın ve 1855 yılındaki depremde ağır hasar almıştır. Son olarak, 1957 yılında Bursa Eski Eserleri Sevenler Derneği tarafından onarılarak yeniden ibadete açılmıştır.", "en": "The mosque is located in Osmangazi District, Nalbantoğlu Neighborhood, on Nalbantoğlu Street No. 2. The building was built by Nalbantbaşı as a neighborhood masjid during the reign of Sultan Murad II, and was converted into a mosque by adding a minbar in 1777.\n\nHistorical sources state that there was a primary school -known by the same name- to the east of the mosque. It is stated that in the graveyard of the school, there are the graves of the imam of the mosque and the teacher of the school, Palancı Hoca Ömer Hulusi Efendi (d. AH 1293 / 1876 AD), the Qadi of Bursa Şâmîzâde Mustafa Efendi (d. AH 1194 / 1780 AD) and Nakibüleşraf Yörükzâde Mehmed Efendi (d. AH 1217 / 1802 AD), as well as the graves of other individuals. Records state that after the primary school, which was used as a school for a long time, was demolished, a few stones from the graves were taken to the Emir Sultan Cemetery.\n\nThe mosque, which has been damaged by various natural disasters since its construction, was severely damaged in the fire of 1518 and the earthquake of 1855. Finally, it was repaired and reopened for worship in 1957 by the Bursa Association for the Appreciation of Antiquities."}, "mimari": {"metin": {"tr": "Yaklaşık 11,00 × 8,00 m ölçülerinde dikdörtgen planlı olan caminin kuzey yönünde, 3,50 × 8,12 m boyutlarında kalkan duvarlı bir son cemaat yeri bulunmaktadır. Bu bölüm yan duvarlarla çevrilmiş, yanlarda geniş, ortada ise dar olmak üzere üç sivri kemerli açıklıkla sonlandırılmıştır. Orta kemerin altında bir Bursa kemeri daha bulunmaktadır. Orta bölmenin üzeri kubbe ile, yan bölümler ise aynalı tonozla örtülmüştür.\n\nSon cemaat mekânının orta giriş kapısı, birbirine geçme iki renk mermerden inşa edilmiş, basık kemerli ve sövelidir. Kapı alınlığı, zülfe taç motifli mermer bir yüzeye sahiptir. Bu yüzeyde, rumi bezemeli sülüs hatla kabartma olarak Nisâ suresi 103. ayet yazılıdır:\n\n“İnne’s-salâte kânet ale’l-mü’minîne kitâben mevkuten- Muhakkak ki namaz, inananlara vakit vakit farz kılınmıştır.”\n\nKapı kemerinin alınlığı tuğla ile bezenmiştir. Caminin cephe detaylarında da benzer malzeme ve süsleme tercih edilmiştir.\n\nBeden duvarları, kuzey cephesi dışında diğer cephelerde alt pencere kemerlerinin üst seviyesine değin üç sıra tuğla ve iki sıra moloz taşla örülmüş, buradan yukarısı ise üç sıra yaba motifli tuğla bezemeli ve bir sıra küfeki taşla devam ettirilmiştir. Üç sıra tuğla ve bir sıra moloz taşla örülen kalkan duvarlı kuzey cephesinde birbirine geçme tekniği uygulanarak, tuğladan yaba motifleriyle zenginlik kazandırılmıştır.\n\nHarim mekânı 7,50 × 7,50 metre iç ölçülerinde kare planlıdır. Harim üzeri, dıştan sekizgen kasnaklı, içeride Türk üçgenleri ve büyük boyda baklava motifli bir kuşakla geçiş sağlanan kurşun kaplı kubbeyle örtülmüştür. Kubbe kasnak saçakları ve kuzeydeki kalkan duvarı saçakları üç sıra testere dişli tuğla ile geçilmiştir.\n\nHarim mekânı, alt ve üst sırada toplam altı pencere ile kubbe kasnağındaki üç pencere sayesinde aydınlatılmaktadır. Mermer söveli alt pencereler dikdörtgen formlu ve sivri kemer alınlıklıdır. Dış cephede tuğla bezeme, iç yüzeyde ise kalem işi süslemeler dikkat çeker. Sivri kemerli üst pencereler alçı şebekeli ve vitraylıdır.\n\nDikdörtgen çerçeveli, yarım beşgen planlı mihrap nişi, altı sıra stalaktitli kavsara ve çerçevesiyle birlikte yağlı boya ile boyanmıştır. Mihrap üst kısmında, Âl-i İmrân suresinin 37. ayeti olan “Küllemâ dehale aleyhâ Zekeriyya’l-mihrâb - Zekeriya ne zaman mihraba girse” ifadesi yer almaktadır. Duvar yüzeylerinde ise dört halifenin isimleri yer almaktadır.\n\nDikdörtgen parçalardan geçme tekniğiyle yapılmış olan ahşap minberin, H. 1191 / M. 1777 tarihinde yapıya eklendiği düşünülmektedir. Cümle kapısının üzerinde sonradan eklenmiş kadınlar mahfili, girişin sağ tarafında da müezzin mahfili yer almaktadır.\n\nBursa’daki benzer yapılar arasında estetik açıdan öne çıkan minare, harimin kuzeydoğusunda yer almaktadır ve iç mekândaki bir kapı aracılığıyla ulaşılmaktadır. Caminin beden duvarlarında kullanılan almaşık örgü sistemi, minarenin çokgen planlı alt kaidesinde de görülmektedir. Tuğladan örülen silindirik gövdenin bitiminde, birbirine geçmeli on iki köşeli geometrik motiflerden oluşan bir bilezik yer alır. Şerefe altı, beş sıra stalaktitli tuğla işçiliğiyle bezenmiş, konik sivri külahı ise kurşunla kaplanmıştır.", "en": "The mosque, which has a rectangular plan measuring approximately 11,00 × 8,00 m, has a narthex with a parapet wall measuring 3,50 × 8,12 m on the north side. This section is surrounded by side walls and ends with three pointed arched openings, wide ones on the sides and a narrow one in the middle. There is another Bursa arch under the middle arch. The middle section is covered with a dome, and the side sections are covered with flattened barrel vaults.\n\nThe middle entrance doorway of the narthex is made of interlocking two-colored marble, and has a depressed arch and a frame. The door pediment has a marble surface with a crown motif. On this surface, the 103rd verse of the Surah an-Nisa is inscribed in relief in Thuluth calligraphy with rumi decoration:\n\n“İnne’s-salâte kanet ale’l-mü’minine kitaben mevkuten- Prayer is indeed made obligatory for the believers from time to time.”\n\nThe pediment of the door arch is decorated with bricks. Similar materials and ornaments are used in the façade details of the mosque.\n\nThe main walls are built with three rows of bricks and two rows of rubble stone up to the upper level of the lower window arches on all façades, and from there on up, they are continued with three rows of brick decorations with pitchfork motifs and one row of limestone. The north façade, which has a parapet wall built with three rows of bricks and one row of rubble stone, is enriched with pitchfork motifs made of bricks by applying the interlocking technique.\n\nThe prayer hall has a square plan with an interior dimension of 7,50 × 7,50 meters. The prayer hall is covered with a lead-coated dome with an octagonal drum on the outside and a belt with Turkish triangles and large lozenge motifs on the inside. The dome drum eaves and the eaves of the parapet wall in the north are covered with three rows of sawtooth bricks.\n\nThe prayer hall is illuminated by a total of six windows in the lower and upper rows and three windows on the dome drum. The lower windows with marble frames are rectangular in form and have pointed arch pediments. The brick decoration on the exterior and the hand-drawn decorations on the interior are striking. The pointed arched upper windows have plaster grilles and stained glass.\n\nThe mihrab niche with a rectangular frame and a half-pentagonal plan, along with the six-row stalactite hood and frame, is painted with oil paint.\n\nOn the upper part of the mihrab, the 37th verse of the Surah Al-Imran, “Kullema dehale aleyha Zekeriyya’l-mihrab” - Whenever Zechariah enters the mihrab” is written on the wall surfaces, the names of the four caliphs are written on the wall surfaces.\n\nIt is thought that the wooden minbar, made of rectangular pieces using an interlocking technique, was added to the building in AH 1191 / AD 1777. There is a women’s section which was later above the main door, and a muezzin’s mahfil on the right side of the entrance.\n\nThe minaret, which stands out aesthetically among similar structures in Bursa, is located to the northeast of the prayer hall and is accessed through a doorway in the interior. The alternating masonry system used in the main walls of the mosque can also be seen in the polygonal base of the minaret. At the end of the cylindrical shaft made of bricks, there is a decorative band consisting of interlocking twelve-sided geometric motifs. The section below the balcony is decorated with, five rows of stalactite brickwork, and the conical pointed spire is covered with lead."}, "plan": "Dikdörtgen plan", "ust_ortu": "Kurşun kaplı kubbe", "malzeme": ["tuğla", "moloz taş", "küfeki taşı", "mermer"], "onarimlar": [{"yil": 1957, "aciklama": {"tr": "Bursa Eski Eserleri Sevenler Derneği tarafından onarılarak yeniden ibadete açılmıştır.", "en": "Repaired and reopened for worship by the Bursa Association for the Appreciation of Antiquities."}, "kaynak_id": "vk-bursa-envanter-c1"}, {"yil": 1777, "aciklama": {"tr": "Minber eklenerek mescit camiye dönüştürüldü.", "en": "A minbar was added and the masjid became a mosque."}, "kaynak_id": "vk-bursa-envanter-c1"}]}, "olgular": [{"metin": {"tr": "Yapı, Sultan II. Murad döneminde Nalbantbaşı tarafından mahalle mescidi olarak inşa ettirilmiştir.", "en": "The building was built by Nalbantbaşı as a neighborhood masjid during the reign of Sultan Murad II."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "405"}, {"metin": {"tr": "Mescit, 1777 yılında minber eklenerek camiye dönüştürülmüştür.", "en": "It was converted into a mosque by adding a minbar in 1777."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "405"}, {"metin": {"tr": "Harim, 7,50 × 7,50 m iç ölçülerinde kare planlı olup kurşun kaplı kubbeyle örtülmüştür.", "en": "The prayer hall has a square plan of 7.50 × 7.50 m and is covered with a lead-coated dome."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "406"}, {"metin": {"tr": "Son cemaat yeri giriş kapısının alınlığında Nisâ suresi 103. ayet kabartma olarak yazılıdır.", "en": "The 103rd verse of the Surah an-Nisa is inscribed in relief on the narthex door pediment."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "406"}, {"metin": {"tr": "Beden duvarları tuğla ve moloz taş almaşık örgüyle inşa edilmiştir.", "en": "The main walls are built with alternating rows of bricks and rubble stone."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "406"}, {"metin": {"tr": "Cami, 1518’deki yangın ve 1855 yılındaki depremde ağır hasar almıştır.", "en": "The mosque was severely damaged in the fire of 1518 and the earthquake of 1855."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "407"}, {"metin": {"tr": "Cami, 1957 yılında Bursa Eski Eserleri Sevenler Derneği tarafından onarılarak yeniden ibadete açılmıştır.", "en": "It was repaired and reopened for worship in 1957 by the Bursa Association for the Appreciation of Antiquities."}, "kategori": "onarim", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "407"}], "envanter": {"kaynak_id": "vk-bursa-envanter-c1", "sayfa": "405-407"}, "konum": {"enlem": 40.182323, "boylam": 29.063877, "dogrulandi": false, "yontem": "osm", "hassasiyet": "eser"}, "gorseller": [{"dosya": "/gorseller/bursa/nalbantoglu-camii/01.webp", "alt": {"tr": "Sokak köşesinde taş-tuğla almaşık duvarlı cami", "en": "Mosque with alternating stone-and-brick walls on a street corner"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/nalbantoglu-camii/02.webp", "alt": {"tr": "Turkuaz mihraplı, kırmızı halılı iç mekân", "en": "Interior with a turquoise mihrab and red carpet"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/nalbantoglu-camii/03.webp", "alt": {"tr": "Mukarnas kavsaralı, turkuaz çerçeveli mihrap", "en": "Mihrab with muqarnas hood in a turquoise frame"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/nalbantoglu-camii/04.webp", "alt": {"tr": "Ahşap kadınlar mahfili ve giriş kapıları", "en": "Wooden women''s gallery and entrance doors"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/nalbantoglu-camii/05.webp", "alt": {"tr": "Kubbesi ve minaresiyle caminin şehir içinden görünümü", "en": "The domed mosque and minaret within the city"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}]}'::jsonb, 'editorde', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'nalbantoglu-camii' and durum = 'yayinda'), 'vk-bursa-envanter-c1', '405', 'Camiye dönüşüm tarihi onarımlara, örtü bilgisi künyeye eklendi.', 'Burak Öztürk', now() - interval '50 hours', 'Doç. Dr. Zeynep Arslan', now() - interval '12 hours', 'Doğru.') returning id into sid;
    values ('kaynak', 'surum', sid, 'nalbantoglu-camii', 'demo', 'tamam', '{"sonuc": "destekliyor", "sayfa": 405, "pasaj": "Mescit, 1777 yılında minber eklenerek camiye dönüştürülmüştür.", "kaynaktaki_deger": "1777", "aciklama": "1777''de minber eklenerek camiye dönüştürüldüğü kaynakta geçiyor.", "guven": "yuksek", "metin": "tamam", "pasaj_dogrulandi": true, "bulunan_sayfa": 405, "sayfali": true, "kaynak_adresi": "https://www.vakifkatilim.com.tr/documents/KurumsalIletisim/yayinlarimiz/bursa-envanteri-cilt-1.pdf", "incelenen_sayfalar": [404, 405, 406]}'::jsonb, 'gemini-flash-lite-latest', 'Sistem', now() - interval '49.5 hours', now() - interval '49.5 hours') returning id into aid;
  -- seyh-ali-cami-ve-kulliyesi-hatay (editorde)
    values ('seyh-ali-cami-ve-kulliyesi-hatay', 'hatay', '{"id": "seyh-ali-cami-ve-kulliyesi-hatay", "ad": {"tr": "Şeyh Ali Cami ve Külliyesi", "en": "The Sheikh Ali Mosque and Complex"}, "tur": "kulliye", "ilce": "Antakya", "donem": {"yaklasik": true, "metin": {"tr": "1580''den önce", "en": "before 1580"}, "yapim_yili": 1580, "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, "konum": {"enlem": 36.2025, "boylam": 36.1605, "dogrulandi": false, "yontem": "geocoding", "hassasiyet": "ilce"}, "envanter": {"kaynak_id": "vk-hatay-envanter", "sayfa": "159"}, "olgular": [{"metin": {"tr": "Külliye, doğu ve batıdan birer girişi olan ve düzensiz bir avlu içerisinde bulunan cami, medrese ve şadırvandan oluşur.", "en": "The complex consists of a mosque, a madrasa and a shadirvan in an irregular courtyard with entrances from the east and west."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "Medrese avlunun kuzeyinde, cami güneyinde, şadırvan ise batısındadır.", "en": "The madrasa is in the north of the courtyard, the mosque is in the south, and the shadirvan is in the west."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "İnşa tarihi 15. yüzyılın ikinci yarısına kadar gidebileceği tahmin edilen, fakat varlığı 1580’de ortaya çıkmış Şeyh Ali Camii, gelenekçi bölgesel mimarinin dar sınırlarını aşarak daha geniş coğrafyalardan nasiplenmiş bir eserdir.", "en": "The Sheikh Ali Mosque, whose construction date is estimated to date back to the second half of the 15 th century, but whose existence was revealed in 1580, is a great work of art that went beyond the narrow limits of traditional regional architecture and benefited from wider geographies."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "Caminin kuzeydoğu köşesinde 2001 yılına kadar iki şerefeli, sonrasında da tek şerefeli hale getirilen minare bulunur.", "en": "In the northeast corner of the mosque, there is a minaret with two balconies until 2001, and then a single balcony."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "Tek şerefeden sonra yüksek petek ve sivri külahla devam eden minare, bu haliyle dahi klasik Osmanlı devri minareleri ile boy ölçüşecek şekilde göz alıcıdır.", "en": "The minaret, which continues with a high honeycomb and pointed cone after a single balcony, is eye-catching even in its current state, competing with the minarets of the classical Ottoman period."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "Türkmenistan’da bulunan, 11. veya 12. yüzyıla tarihlenen Talhatan Baba Camii’nde değerlendirilmiş planın asırlar sonra Antakya’da neşet bulması oldukça hayret vericidir.", "en": "It is quite astonishing that the plan, which was used in the Talhatan Baba Mosque in Turkmenistan, dated to the 11 th or 12 th century, appeared in Antakya centuries later."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "Cami planı, anıtsal mimarisi, Antakya’daki en zengin tezyinata sahip eserlerden birisi olması cihetiyle şehrin mimarisinde oldukça saygın bir yere sahiptir.", "en": "Due to its mosque plan, monumental architecture, and being one of the richest decorated works in Antakya, it has a very respectable place in the city’s architecture."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "Tamamı beyaz kalker taş malzeme ile oldukça düzgün bir işçilikle inşa edilen Şeyh Ali Camii, kuzey duvarına bitişik son cemaat yeriyle birlikte avlunun güneyinde yer almaktadır.", "en": "The Sheikh Ali Mosque, which was built with a very neat workmanship with white limestone stone material, is located in the south of the courtyard with the narthex adjacent to the north wall."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "Köşelerde “L” şeklindeki ayaklara ve bunlar arasında ince mermer sütunlara oturtulmuş sivri kemerlerden müteşekkil son cemaat yeri, diğer Antakya cami ve mescitleri gibi ahşap sundurma ile örtülmüştür.", "en": "The narthex, which consists of pointed arches placed on “L” shaped feet at the corners and thin marble columns between them, is covered with a wooden porch like other Antakya mosques and masjids."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "Bu örtünün, harimin kuzeydeki heybetli taç kapıyı ikiye bölmek suretiyle alınlıkta bulunan ikiz pencereyi önemli ölçüde işlevsiz bıraktığını da belirtmek gerekir.", "en": "It should also be noted that this cover divides the majestic portal in the north of the sanctuary into two, leaving the twin window in the pediment significantly dysfunctional."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "Bununla beraber, kapıda iki yanda birer zarif sütun üzerine oturtulmuş baş kemerle kuşatılan siyah beyaz taş işçilik, üstteki ikiz pencere ve bunların arasına yerleştirilen gemi çarkı şekline benzer yuvarlak pencere, taç kapının ne kadar özen ve emekle yapıldığının birer delilidir.", "en": "In addition, the black and white stone workmanship, surrounded by a head arch, which is placed on an elegant column on each side of the door, the twin window at the top and the round window resembling a ship’s wheel placed between them, are the proofs of how the portal was built with care and efforts."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "Kapı açıklığıyla baş kemer arasına yerleştirilen altı satırlık kitabe ise bu emeğin mührü gibidir.", "en": "The six-line inscription placed between the door opening and the head arch is like the seal of this labor."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "Harim kısmı, son cemaat yerinden daha yüksek tutulmak suretiyle önemli ölçüde vurgulanmıştır.", "en": "The sanctuary is emphasized significantly by being placed higher than the narthex."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "Bu kornişler Türk mimarisinde 19. yüzyıl sonlarında ve 20. yüzyılın başlarında Batı tesiri olarak değerlendirilir.", "en": "This form of craftsmanship can be seen as a product of the effort to achieve innovation."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176"}, {"metin": {"tr": "Medrese hücrelerinden batıda bulunan üçüncü hücrenin kapısı üzerine yerleştirilmiş kitabe, medresenin 1903’te Halefzâde Cemil Ağa tarafından yaptırıldığını göstermektedir.", "en": "The inscription placed above the door of the third cell on the west side of the madrasa shows that the madrasa was built in 1903 by Halefzâde Cemil Ağa."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "159-176", "en_ceviri": "yz"}], "gorseller": [{"dosya": "/gorseller/hatay/seyh-ali-cami-ve-kulliyesi-hatay/03.webp", "alt": {"tr": "Şeyh Ali Cami ve Külliyesi, fotoğraf 3", "en": "The Sheikh Ali Mosque and Complex, photo 3"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}, {"dosya": "/gorseller/hatay/seyh-ali-cami-ve-kulliyesi-hatay/01.webp", "alt": {"tr": "Şeyh Ali Cami ve Külliyesi, fotoğraf 1", "en": "The Sheikh Ali Mosque and Complex, photo 1"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}, {"dosya": "/gorseller/hatay/seyh-ali-cami-ve-kulliyesi-hatay/02.webp", "alt": {"tr": "Şeyh Ali Cami ve Külliyesi, fotoğraf 2", "en": "The Sheikh Ali Mosque and Complex, photo 2"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}, {"dosya": "/gorseller/hatay/seyh-ali-cami-ve-kulliyesi-hatay/04.webp", "alt": {"tr": "Şeyh Ali Cami ve Külliyesi, fotoğraf 4", "en": "The Sheikh Ali Mosque and Complex, photo 4"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}], "mimari": {"onarimlar": [{"yil": 2001, "aciklama": {"tr": "İki şerefeli minare tek şerefeli olarak yenilendi.", "en": "The two-balcony minaret was rebuilt with a single balcony."}, "kaynak_id": "vk-hatay-envanter"}]}}'::jsonb, 'editorde', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'seyh-ali-cami-ve-kulliyesi-hatay' and durum = 'yayinda'), 'vk-hatay-envanter', '159-176', 'Minare yenilemesi onarımlara eklendi.', 'Elif Şahin', now() - interval '44 hours', 'Doç. Dr. Zeynep Arslan', now() - interval '5 hours', 'Kaynakla uyumlu.') returning id into sid;
    values ('kaynak', 'surum', sid, 'seyh-ali-cami-ve-kulliyesi-hatay', 'demo', 'tamam', '{"sonuc": "destekliyor", "sayfa": null, "pasaj": "Caminin kuzeydoğu köşesinde 2001 yılına kadar iki şerefeli, sonrasında da tek şerefeli hale getirilen minare bulunur.", "kaynaktaki_deger": "2001 yılına kadar iki şerefeli, sonrasında tek şerefeli", "aciklama": "Kaynak 2001''deki değişikliği anlatıyor.", "guven": "yuksek", "metin": "tamam", "pasaj_dogrulandi": true, "bulunan_sayfa": null, "sayfali": true, "kaynak_adresi": "https://www.vakifkatilim.com.tr/documents/KurumsalIletisim/hatay-vakif-eserleri.pdf", "incelenen_sayfalar": []}'::jsonb, 'gemini-flash-lite-latest', 'Sistem', now() - interval '43.5 hours', now() - interval '43.5 hours') returning id into aid;
  -- karakurt-camii-konya (reddedildi)
    values ('karakurt-camii-konya', 'konya', '{"id": "karakurt-camii-konya", "ad": {"tr": "Karakurt Camii", "en": "Karakurt Mosque"}, "tur": "cami", "ilce": "Meram", "adres": {"tr": "Cami, Meram, Karakurt Mahallesi, Birhan Sokak, No. 11’de yer almaktadır.", "en": "The mosque is located in Meram District, Karakurt Neighborhood, Birhan Street No: 11."}, "donem": {"yapim_yili": 1945, "kaynak_id": "vk-konya-envanter-c1", "sayfa": "81"}, "konum": {"enlem": 37.865625, "boylam": 32.498641, "dogrulandi": false, "yontem": "geocoding", "hassasiyet": "eser"}, "envanter": {"kaynak_id": "vk-konya-envanter-c1", "sayfa": "81"}, "olgular": [{"metin": {"tr": "Cami, Meram, Karakurt Mahallesi, Birhan Sokak, No. 11’de yer almaktadır.", "en": "The mosque is located in Meram District, Karakurt Neighborhood, Birhan Street No: 11."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "81"}, {"metin": {"tr": "Yapı 1954 senesinde, Cumhuriyet dönemi geleneksel mimari özelliklerine haiz şekilde yapılmıştır.", "en": "The building was built in 1954, with traditional architectural features of the Republican Era."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "81"}, {"metin": {"tr": "Üzerine yapıldığı arazinin şartlarına göre betonarme olarak yapılmış olan cami, düzgün bir plana sahip değildir.", "en": "The mosque, which was built of reinforced concrete according to the conditions of the land on which it was built, does not have a proper plan."}, "kategori": "onarim", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "81"}, {"metin": {"tr": "Enine dikdörtgen şekilde, iki sahınlı olarak yapılmış caminin alt katı depo olarak inşa edilmiştir.", "en": "The lower floor of the mosque, which is built in a transverse rectangular shape with two naves, was built as a warehouse."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "81"}, {"metin": {"tr": "Harim mekânı da iki sahınlıdır.", "en": "The harim space also has two naves."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "81"}, {"metin": {"tr": "Kıble duvarının ortasındaki mihrap, dışa doğru taşıntılı ve yarım daire planlıdır.", "en": "The mihrab in the middle of the qibla wall projects outward and has a semicircular plan."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "81"}, {"metin": {"tr": "Caminin baldaken minaresi Konya bölgesindeki minarelerin devamı niteliğindedir.", "en": "The baldachin minaret of the mosque is a continuation of the minarets in the Konya region."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-konya-envanter-c1", "sayfa": "81"}], "gorseller": [{"dosya": "/gorseller/konya/karakurt-camii-konya/01.webp", "alt": {"tr": "Karakurt Camii, fotoğraf 1", "en": "Karakurt Mosque, photo 1"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Konya Vakıf Eserleri Envanteri", "kaynak_id": "vk-konya-envanter-c1"}, {"dosya": "/gorseller/konya/karakurt-camii-konya/02.webp", "alt": {"tr": "Karakurt Camii, fotoğraf 2", "en": "Karakurt Mosque, photo 2"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Konya Vakıf Eserleri Envanteri", "kaynak_id": "vk-konya-envanter-c1"}, {"dosya": "/gorseller/konya/karakurt-camii-konya/03.webp", "alt": {"tr": "Karakurt Camii, fotoğraf 3", "en": "Karakurt Mosque, photo 3"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Konya Vakıf Eserleri Envanteri", "kaynak_id": "vk-konya-envanter-c1"}]}'::jsonb, 'reddedildi', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'karakurt-camii-konya' and durum = 'yayinda'), 'vk-konya-envanter-c1', null, 'Yapım yılı düzeltildi.', 'Burak Öztürk', now() - interval '120 hours', 'Doç. Dr. Zeynep Arslan', now() - interval '110 hours', 'Envanter kitabı 1954 diyor; 1945 kaynakla çelişiyor.') returning id into sid;
  -- pasa-camii (reddedildi)
    values ('pasa-camii', 'bursa', '{"id": "pasa-camii", "ad": {"tr": "Paşa Camii", "en": "Paşa Mosque"}, "tur": "cami", "ilce": "Osmangazi", "adres": {"tr": "Alacahırka Mahallesi, Orhaneli Caddesi, No: 39, Osmangazi, Bursa", "en": "Alacahırka Neighborhood, Orhaneli Street, No. 39, Osmangazi, Bursa"}, "donem": {"yapim_yili": 1901, "yapim_yili_hicri": 1319, "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "408"}, "tarihce": {"tr": "Paşa Camii, Osmangazi ilçesi, Alacahırka Mahallesi, Orhaneli Caddesi, No: 39’da yer almaktadır.\n\nKitabesi bulunmayan caminin kimin tarafından yaptırıldığı kesin olarak bilinmemektedir. Bir görüşe göre H. 1323-1325 / M. 1905-1907 yıllarında bölge halkı tarafından inşa edildiği, diğer bir görüşe göre ise H. 1319 / M. 1901 tarihinde Ahmet Vefik Paşa döneminde, Kırım’dan göç ederek bu civara yerleşen muhacirler tarafından yaptırıldığı düşünülmektedir.", "en": "Paşa Mosque is located in Osmangazi District, Alacahırka Neighborhood, on Orhaneli Street, No. 39.\n\nIt is not known for sure who built the mosque, which has no inscription. According to one view, it was built by the local people in AH 1323-1325 / AD 1905-1907, and according to another view, it was built by the immigrants who migrated from Crimea and settled in this area during the time of Ahmet Vefik Paşa in AH 1319 / AD 1901."}, "mimari": {"metin": {"tr": "Meyilli bir arazide konumlanmış olması nedeniyle yol kotundan yüksekte kalan giriş kapısına on basamaklı bir merdivenle ulaşılmaktadır. Merdivenlerin altındaki bölümde abdestlik ve helalar yer almaktadır. Birçok kez onarımdan geçirilen cami, özgün yapısını büyük ölçüde yitirmiştir.\n\n10.00 × 14.00 m ölçülerinde dikdörtgen planlı yapının üzeri ahşap kırma çatı ve kiremitle örtülüdür. Duvarla çevrili kapalı bir son cemaat mahalline sahip olan caminin harimi kare planlıdır ve yaklaşık 100 m²’lik bir alanı kapsamaktadır.\n\nCami içten ve dıştan tamamen beton sıvalıdır. Kuzeybatı köşesinde bulunan küçük ebatlı, silindirik formdaki minarenin tek şerefesinin altı stalaktitlidir. Konik sivri külahı betondan yapılan minare tamamen sıvalıdır.\n\nAhşap tavanlı harim, altta sekiz, üstte ise beş adet dikdörtgen pencere ile aydınlatılmaktadır. Minberi ahşap olan caminin mihrap nişi, dilimli beyaz mermerle kaplanmıştır. Hanımlar mahfili ise kuzey girişinin üzerindedir.", "en": "The entrance door, which is above the road level due to its location on sloping land, is reached by a ten-step staircase. In the section under the stairs, there are ablution facilities and toilets. The mosque, which has been repaired many times, has lost much of its original structure.\n\nThe rectangular planned building, measuring 10.00 × 14.00 m, is covered with a wooden hipped roof and tiles. The mosque has a closed narthex surrounded by walls, and its prayer hall has a square plan and covers an area of approximately 100 m².\n\nThe mosque is completely plastered with concrete both inside and outside. The single balcony of the small-sized, cylindrical minaret located in the northwest corner has stalactites underneath. The minaret, whose conical pointed spire is made of concrete, is completely plastered.\n\nThe prayer hall with a wooden ceiling is illuminated by eight rectangular windows at the bottom and five at the top. The mosque’s minbar is made of wood and its mihrab niche is covered with panels of white marble. The women’s gallery is above the north entrance."}, "plan": "Dikdörtgen plan", "ust_ortu": "Kiremitle örtülü ahşap kırma çatı"}, "olgular": [{"metin": {"tr": "Kitabesi bulunmayan caminin kimin tarafından yaptırıldığı kesin olarak bilinmemektedir.", "en": "It is not known for sure who built the mosque, which has no inscription."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "408"}, {"metin": {"tr": "Bir görüşe göre cami H. 1323-1325 / M. 1905-1907 yıllarında bölge halkı tarafından inşa edilmiştir.", "en": "According to one view, it was built by the local people in AH 1323-1325 / AD 1905-1907."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "408"}, {"metin": {"tr": "Diğer bir görüşe göre cami H. 1319 / M. 1901 tarihinde Kırım’dan gelen muhacirler tarafından yaptırılmıştır.", "en": "According to another view, it was built by immigrants from Crimea in AH 1319 / AD 1901."}, "kategori": "tarihce", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "408"}, {"metin": {"tr": "Giriş kapısına on basamaklı bir merdivenle ulaşılmaktadır.", "en": "The entrance door is reached by a ten-step staircase."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "408"}, {"metin": {"tr": "Yapı 10.00 × 14.00 m ölçülerinde dikdörtgen planlıdır.", "en": "The rectangular planned building measures 10.00 × 14.00 m."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "405"}, {"metin": {"tr": "Birçok kez onarımdan geçirilen cami, özgün yapısını büyük ölçüde yitirmiştir.", "en": "The mosque, which has been repaired many times, has lost much of its original structure."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-bursa-envanter-c1", "sayfa": "408"}], "envanter": {"kaynak_id": "vk-bursa-envanter-c1", "sayfa": "408"}, "konum": {"enlem": 40.181574, "boylam": 29.046774, "dogrulandi": false, "yontem": "geocoding", "hassasiyet": "mahalle"}, "gorseller": [{"dosya": "/gorseller/bursa/pasa-camii/01.webp", "alt": {"tr": "Yamaçtaki evler arasında caminin minaresi", "en": "The mosque''s minaret among hillside houses"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/pasa-camii/02.webp", "alt": {"tr": "Caminin kiremit çatısının kuşbakışı görünümü", "en": "Bird''s-eye view of the mosque''s tiled roof"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}, {"dosya": "/gorseller/bursa/pasa-camii/03.webp", "alt": {"tr": "Mavi halılı iç mekân, mihrap ve minber", "en": "Blue-carpeted interior with mihrab and minbar"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Bursa Vakıf Eserleri", "kaynak_id": "vk-bursa-envanter-c1"}], "banisi": "Kırım muhacirleri"}'::jsonb, 'reddedildi', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'pasa-camii' and durum = 'yayinda'), 'vk-bursa-envanter-c1', null, 'Bânî eklendi.', 'Selin Aydın', now() - interval '96 hours', 'Doç. Dr. Zeynep Arslan', now() - interval '90 hours', 'Kaynakta iki ayrı görüş var; tek görüş künyeye kesin bilgi gibi yazılamaz. Olgu olarak eklenebilir.') returning id into sid;
  -- ali-cavus-mescidi-hatay (reddedildi)
    values ('ali-cavus-mescidi-hatay', 'hatay', '{"id": "ali-cavus-mescidi-hatay", "ad": {"tr": "Ali Çavuş Mescidi", "en": "Ali Çavuş Masjid"}, "tur": "mescit", "ilce": "Antakya", "konum": {"enlem": 36.2025, "boylam": 36.1605, "dogrulandi": false, "yontem": "geocoding", "hassasiyet": "ilce"}, "envanter": {"kaynak_id": "vk-hatay-envanter", "sayfa": "194"}, "olgular": [{"metin": {"tr": "Mescit eski Antakya’nın iş ve ticaret hayatının bel kemiğini oluşturan Uzun Çarşı üzerinde bulunmaktadır.", "en": "The Masjid is located on Uzun Bazaar which constitutes the backbone of business and commercial life of ancient Antakya."}, "kategori": "gunumuz", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "194-197"}, {"metin": {"tr": "Tahmini olarak 1872 depreminden hemen sonra yapılmıştır ve muhtemelen bir evin mescide dönüştürülmesiyle elde edilen mütevazı bir yapıdır.", "en": "It was probably built right after the 1872 earthquake and it is a modest building that was probably obtained by converting a house into a masjid."}, "kategori": "onarim", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "194-197"}, {"metin": {"tr": "Yapı gayrimuntazam bir avluya ve ahşap düz tavanla örtülmüş yamuk plan üzerine oturtulmuş ibadet mekânına sahiptir.", "en": "The building has an irregular courtyard and a place of worship on a trapezoidal plan covered with a wooden flat ceiling."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "194-197"}, {"metin": {"tr": "Mihrabın kapı ekseninde olmaması, simetriden mahrum kapı ve pencereler yapının evden mescide dönüştürülmüş olmasının delilidir.", "en": "The fact that the mihrab is not on the door axis and the doors and windows deprived of symmetry are evidence of the fact that the building was converted from a house into a mosque."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "194-197"}, {"metin": {"tr": "Kuzeyde uzun, güneyde kısa kenarları paralel, doğu ve batı kenarları ise yamuk olan mescide, doğu cephesinde yer alan sade bir kapıdan girilmektedir.", "en": "The masjid, which is long in the north, parallel in the short sides in the south, and trapezoidal in the east and west, is entered through a plain door on the east side."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "194-197"}, {"metin": {"tr": "Mescit, kapının batısında iki, güney duvarında ise çok sade bir girintiden ibaret mihraba sahiptir.", "en": "The masjid has two mihrabs on the west of the gate and a very plain recess on the south wall."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "194-197"}, {"metin": {"tr": "Mihrap yan taraflarında birer, doğu duvarında da iki tane olmak üzere toplam altı pencereden ışık almaktadır.", "en": "The mihrab receives light from a total of six windows, one on each side and two on the east wall."}, "kategori": "mimari", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "194-197"}, {"metin": {"tr": "Hiçbir tezyinatı bulunmayan eser, en son 1993 yılında onarım görmüştür, bu restorasyon esnasında mihrabın iki yanında yer alan pencereler kapatılmıştır.", "en": "The work, which has no ornaments, was last repaired in 1993, the windows on both sides of the mihrab were closed during this repair."}, "kategori": "onarim", "durum": "kaynakli", "kaynak_id": "vk-hatay-envanter", "sayfa": "194-197"}], "gorseller": [{"dosya": "/gorseller/hatay/ali-cavus-mescidi-hatay/02.webp", "alt": {"tr": "Ali Çavuş Mescidi, fotoğraf 2", "en": "Ali Çavuş Masjid, photo 2"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}, {"dosya": "/gorseller/hatay/ali-cavus-mescidi-hatay/01.webp", "alt": {"tr": "Ali Çavuş Mescidi, fotoğraf 1", "en": "Ali Çavuş Masjid, photo 1"}, "lisans": "Tüm hakları saklıdır", "atif": "Vakıf Katılım, Hatay İli Vakıf Eserleri", "kaynak_id": "vk-hatay-envanter"}], "donem": {"yapim_yili": 1872}}'::jsonb, 'reddedildi', 'duzenle', (select max(id) from eser_surumleri where eser_id = 'ali-cavus-mescidi-hatay' and durum = 'yayinda'), 'vk-hatay-envanter', null, 'Yapım yılı 1872 olarak girildi.', 'Elif Şahin', now() - interval '80 hours', 'Murat Kaplan', now() - interval '60 hours', 'Kaynak ''tahminen 1872 depreminden hemen sonra'' diyor; kesin yıl değil, ''yaklaşık'' işaretlenmeli.') returning id into sid;
